import type { BankQuestion } from "@/lib/bank";

/** Sectors of the Economy and Government Schemes (Indian Economy): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "eco-sectors-schemes-2", "question": "The Swachh Bharat Mission was launched on 2 October 2014 to mark the birth anniversary of:", "options": ["B.R. Ambedkar", "Sardar Vallabhbhai Patel", "Mahatma Gandhi", "Jawaharlal Nehru"], "answer": 2, "explanation": "It was launched on Gandhi Jayanti, with the aim of an open-defecation-free India by Gandhi's 150th birth anniversary in 2019.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-3", "question": "Under PM-KISAN, launched in 2019, how much income support does an eligible farmer family receive in a year?", "options": ["₹6,000", "₹2,000", "₹12,000", "₹10,000"], "answer": 0, "explanation": "₹6,000 a year is paid in three instalments of ₹2,000 each, directly into the farmer's bank account.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-4", "question": "The Pradhan Mantri Ujjwala Yojana, launched in 2016, provides:", "options": ["Free health insurance to the poor", "Free LPG connections to women of poor households", "Free bank accounts to women", "Free electricity connections to villages"], "answer": 1, "explanation": "Ujjwala gives deposit-free LPG connections in the name of adult women of poor families, to replace firewood and cow-dung cooking fuel.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-5", "question": "How many days of guaranteed wage employment per year does MGNREGA, enacted in 2005, give a rural household?", "options": ["150 days", "365 days", "200 days", "100 days"], "answer": 3, "explanation": "The Act guarantees 100 days of unskilled manual work per household per financial year. 150 days applies only in special cases such as drought-hit areas or forest-rights holders.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-6", "question": "The Digital India programme, launched on 1 July 2015, is steered by which ministry?", "options": ["Ministry of Communications", "Ministry of Electronics and Information Technology", "Ministry of Science and Technology", "Ministry of Finance"], "answer": 1, "explanation": "MeitY is the nodal ministry for Digital India, whose three pillars are digital infrastructure, services on demand and digital literacy.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-7", "question": "Under the Pradhan Mantri MUDRA Yojana, launched in 2015, the ‘Shishu’ category covers loans of up to:", "options": ["₹50,000", "₹1 lakh", "₹5 lakh", "₹10 lakh"], "answer": 0, "explanation": "Shishu: up to ₹50,000; Kishore: ₹50,000 to ₹5 lakh; Tarun: ₹5 lakh to ₹10 lakh (a Tarun Plus slab up to ₹20 lakh was added in 2024).", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-8", "question": "According to the Periodic Labour Force Survey 2023-24, which sector employs the largest share of India's workforce?", "options": ["Construction", "Trade, hotels and restaurants", "Agriculture", "Manufacturing"], "answer": 2, "explanation": "Agriculture still employs about 46% of workers, even though services contribute the largest share of GVA.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-9", "question": "Ayushman Bharat – PM-JAY, launched in 2018, gives a health cover per family per year of:", "options": ["₹10 lakh", "₹1 lakh", "₹5 lakh", "₹2 lakh"], "answer": 2, "explanation": "PM-JAY covers up to ₹5 lakh per family per year for secondary and tertiary hospitalisation in empanelled hospitals.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-10", "question": "The Soil Health Card Scheme was launched in February 2015 at:", "options": ["Ballia, Uttar Pradesh", "Sehore, Madhya Pradesh", "Gorakhpur, Uttar Pradesh", "Suratgarh, Rajasthan"], "answer": 3, "explanation": "It was launched at Suratgarh (Sri Ganganagar). PM-KISAN was launched at Gorakhpur (2019), PM Ujjwala at Ballia (2016) and PMFBY at Sehore (2016).", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-11", "question": "The Startup India initiative, launched on 16 January 2016, is coordinated by:", "options": ["NITI Aayog", "Department for Promotion of Industry and Internal Trade (DPIIT)", "Ministry of MSME", "Reserve Bank of India"], "answer": 1, "explanation": "DPIIT, under the Ministry of Commerce and Industry, recognises startups and runs the Startup India programme.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-12", "question": "The Atal Pension Yojana, launched in 2015, is administered by:", "options": ["PFRDA", "SEBI", "LIC", "IRDAI"], "answer": 0, "explanation": "The Pension Fund Regulatory and Development Authority administers APY, which guarantees a monthly pension of ₹1,000 to ₹5,000 after age 60 to those who join between 18 and 40.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-13", "question": "Under the Pradhan Mantri Fasal Bima Yojana, launched in 2016, what is the maximum premium a farmer pays for Rabi food and oilseed crops?", "options": ["0.5% of the sum insured", "1.5% of the sum insured", "5% of the sum insured", "2% of the sum insured"], "answer": 1, "explanation": "Farmers pay 2% for Kharif, 1.5% for Rabi and 5% for annual commercial or horticultural crops; the government pays the rest.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-14", "question": "Stand-Up India, launched in 2016, helps SC/ST and women entrepreneurs get bank loans in which range for greenfield enterprises?", "options": ["₹10 lakh to ₹1 crore", "₹50,000 to ₹5 lakh", "₹1 crore to ₹5 crore", "Up to ₹10 lakh"], "answer": 0, "explanation": "Each bank branch is expected to give at least one SC/ST and one woman borrower a loan between ₹10 lakh and ₹1 crore. Loans up to ₹10 lakh fall under MUDRA.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-15", "question": "PM SVANidhi, launched in June 2020, provides collateral-free working capital loans to:", "options": ["Self-help groups", "Small farmers", "Artisans in traditional trades", "Street vendors"], "answer": 3, "explanation": "PM SVANidhi, run by the Ministry of Housing and Urban Affairs, began with ₹10,000 loans so street vendors could restart after the COVID-19 lockdown. Artisans are covered by PM Vishwakarma.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-16", "question": "Under the MSME classification revised in 2020, a micro enterprise has investment up to ₹1 crore and annual turnover up to:", "options": ["₹1 crore", "₹10 crore", "₹5 crore", "₹50 crore"], "answer": 2, "explanation": "2020 criteria: micro ≤ ₹1 crore investment and ≤ ₹5 crore turnover; small ≤ ₹10 crore and ≤ ₹50 crore; medium ≤ ₹50 crore and ≤ ₹250 crore.", "difficulty": "hard", "source": "IBPS PO · SBI PO · State PSC"},
  {"id": "eco-sectors-schemes-17", "question": "Which of the following is NOT one of the eight core industries tracked by the Index of Eight Core Industries?", "options": ["Textiles", "Natural gas", "Cement", "Fertilizers"], "answer": 0, "explanation": "The eight core industries are coal, crude oil, natural gas, refinery products, fertilizers, steel, cement and electricity. Textiles is not among them.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-18", "question": "The National Agriculture Market (e-NAM), launched in April 2016, is implemented by:", "options": ["Food Corporation of India", "NAFED", "Small Farmers' Agribusiness Consortium (SFAC)", "NABARD"], "answer": 2, "explanation": "SFAC, under the Ministry of Agriculture and Farmers Welfare, is the lead agency for e-NAM, the online trading portal that links APMC mandis.", "difficulty": "hard", "source": "IBPS PO · SBI PO · State PSC"},
  {"id": "eco-sectors-schemes-19", "question": "The Kisan Credit Card scheme, introduced in 1998, was based on the recommendations of which committee?", "options": ["Narasimham Committee", "Rangarajan Committee", "M.S. Swaminathan Committee", "R.V. Gupta Committee"], "answer": 3, "explanation": "NABARD prepared the KCC scheme on the R.V. Gupta Committee's recommendations to give farmers timely, flexible credit. Narasimham dealt with banking reforms.", "difficulty": "hard", "source": "IBPS PO · SBI PO · State PSC"},
  {"id": "eco-sectors-schemes-20", "question": "After the 2022 revision, what are the life cover and annual premium under the Pradhan Mantri Jeevan Jyoti Bima Yojana (launched in 2015)?", "options": ["₹5 lakh cover for ₹436 a year", "₹2 lakh cover for ₹436 a year", "₹1 lakh cover for ₹330 a year", "₹2 lakh cover for ₹20 a year"], "answer": 1, "explanation": "PMJJBY gives ₹2 lakh life cover for ₹436 a year (raised from ₹330 in 2022). ₹20 a year is the premium of PMSBY, the accident cover scheme.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-21", "question": "The PM Vishwakarma scheme, launched on 17 September 2023, is implemented mainly by which ministry?", "options": ["Ministry of Social Justice and Empowerment", "Ministry of Rural Development", "Ministry of Micro, Small and Medium Enterprises", "Ministry of Textiles"], "answer": 2, "explanation": "The MSME Ministry runs it jointly with the Ministry of Skill Development and the Department of Financial Services, to support artisans in traditional trades.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-22", "question": "The Sukanya Samriddhi Yojana was launched in January 2015 as part of which campaign?", "options": ["Digital India", "Jan Dhan Yojana", "Swachh Bharat Mission", "Beti Bachao Beti Padhao"], "answer": 3, "explanation": "Both were launched at Panipat on 22 January 2015. Sukanya Samriddhi is a small savings account for a girl child below 10 years.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-23", "question": "The Jal Jeevan Mission, announced in 2019 to provide tap-water connections to every rural household, comes under which ministry?", "options": ["Ministry of Environment, Forest and Climate Change", "Ministry of Jal Shakti", "Ministry of Housing and Urban Affairs", "Ministry of Rural Development"], "answer": 1, "explanation": "The Ministry of Jal Shakti, formed in 2019 by merging the water resources and drinking water ministries, runs the ‘Har Ghar Jal’ mission.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-24", "question": "The SVAMITVA scheme, launched on National Panchayati Raj Day (24 April) in 2020, aims to:", "options": ["Give rural households property cards by mapping village land with drones", "Give crop loans to tenant farmers", "Build pucca houses for the rural poor", "Provide solar pumps to farmers"], "answer": 0, "explanation": "SVAMITVA, run by the Ministry of Panchayati Raj, surveys inhabited village land with drones and issues ‘record of rights’ cards that owners can use to take loans.", "difficulty": "hard", "source": "IBPS PO · SBI PO · State PSC"},
  {"id": "eco-sectors-schemes-25", "question": "Arrange these schemes in the order they were launched: 1. Pradhan Mantri Jan Dhan Yojana 2. PM-KISAN 3. Stand-Up India 4. Pradhan Mantri MUDRA Yojana", "options": ["1, 3, 4, 2", "1, 4, 3, 2", "4, 1, 3, 2", "1, 4, 2, 3"], "answer": 1, "explanation": "Jan Dhan (August 2014), MUDRA (April 2015), Stand-Up India (April 2016), PM-KISAN (February 2019). Order: 1, 4, 3, 2.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-26", "question": "Match the scheme with its nodal ministry: 1. PM Ujjwala Yojana 2. PMAY-Gramin 3. PM MITRA parks 4. PM-JAY; a. Health and Family Welfare b. Textiles c. Rural Development d. Petroleum and Natural Gas", "options": ["1-d, 2-c, 3-b, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-b, 3-c, 4-a", "1-d, 2-c, 3-a, 4-b"], "answer": 0, "explanation": "Ujjwala – Petroleum and Natural Gas, PMAY-G – Rural Development, PM MITRA (mega textile parks, 2021) – Textiles, PM-JAY – Health and Family Welfare (implemented through the National Health Authority).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · State PSC"},
  {"id": "eco-sectors-schemes-27", "question": "How many of these statements about the Pradhan Mantri MUDRA Yojana are correct? I. It was launched in April 2015. II. The ‘Kishore’ category covers loans from ₹50,000 to ₹5 lakh. III. The ‘Tarun’ category covers loans from ₹5 lakh to ₹10 lakh. IV. MUDRA loans can be given only for crop cultivation.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: MUDRA funds non-farm micro enterprises in manufacturing, trading and services, plus activities allied to agriculture, not crop loans.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-28", "question": "Assertion (A): PM-KISAN money is transferred directly into the bank accounts of beneficiary farmers. Reason (R): PM-KISAN is a Central Sector Scheme fully funded by the Government of India.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 1, "explanation": "Both are true, but the direct transfer comes from the scheme's Direct Benefit Transfer design, not from who funds it. A centrally funded scheme could in principle pay out through other channels.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · State PSC"},
  {"id": "eco-sectors-schemes-29", "question": "Under the MSME criteria notified in 2020, an enterprise with ₹8 crore invested in plant and machinery and an annual turnover of ₹60 crore is classified as:", "options": ["Micro", "Large", "Small", "Medium"], "answer": 3, "explanation": "Both limits must be met. Investment ₹8 crore fits ‘small’ (≤ ₹10 crore), but turnover ₹60 crore exceeds the small limit of ₹50 crore, so it is ‘medium’ (≤ ₹50 crore investment, ≤ ₹250 crore turnover).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · State PSC"},
  {"id": "eco-sectors-schemes-30", "question": "How many of these statements about the Pradhan Mantri Fasal Bima Yojana are correct? I. It was launched in 2016, replacing NAIS and the modified NAIS. II. The farmer's premium for annual commercial and horticultural crops is 5%. III. It is run by the Ministry of Agriculture and Farmers Welfare. IV. Since Kharif 2020, enrolment is voluntary for all farmers, including loanee farmers.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Before 2020, enrolment was compulsory for farmers taking crop loans; the 2020 revamp made it voluntary for everyone.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · State PSC"},
  {"id": "eco-sectors-schemes-31", "question": "Match the scheme with its main beneficiaries: 1. PM SVANidhi 2. Stand-Up India 3. PM Vishwakarma 4. PM-KUSUM; a. Artisans and craftspeople b. Street vendors c. Farmers installing solar pumps d. SC/ST and women entrepreneurs", "options": ["1-b, 2-a, 3-d, 4-c", "1-d, 2-b, 3-a, 4-c", "1-b, 2-d, 3-c, 4-a", "1-b, 2-d, 3-a, 4-c"], "answer": 3, "explanation": "SVANidhi – street vendors, Stand-Up India – SC/ST and women entrepreneurs, PM Vishwakarma – artisans, PM-KUSUM (2019) – solar pumps and solar plants for farmers.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-32", "question": "Which pair of scheme and launch year is NOT correct?", "options": ["PM Garib Kalyan Anna Yojana – 2016", "Smart Cities Mission – 2015", "Make in India – 2014", "PM Gati Shakti – 2021"], "answer": 0, "explanation": "PM Garib Kalyan Anna Yojana began in April 2020 as COVID-19 food relief. Make in India (September 2014), Smart Cities Mission (June 2015) and PM Gati Shakti (October 2021) are correct.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-33", "question": "Assertion (A): MGNREGA, enacted in 2005, is called a demand-driven scheme. Reason (R): If work is not given within 15 days of applying, the applicant is entitled to an unemployment allowance.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: work must be provided whenever a household demands it, and the legal penalty of an unemployment allowance is what makes the guarantee demand-driven rather than budget-capped.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · State PSC"},
  {"id": "eco-sectors-schemes-34", "question": "Arrange these agricultural initiatives in the order they were launched: 1. e-NAM 2. Kisan Credit Card 3. PM-KUSUM 4. Soil Health Card", "options": ["2, 4, 3, 1", "2, 1, 4, 3", "4, 2, 1, 3", "2, 4, 1, 3"], "answer": 3, "explanation": "Kisan Credit Card (1998), Soil Health Card (February 2015), e-NAM (April 2016), PM-KUSUM (2019). Order: 2, 4, 1, 3.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · State PSC"},
  {"id": "eco-sectors-schemes-35", "question": "A 30-year-old enrols in both PMJJBY and PMSBY in 2023. What is the total annual premium?", "options": ["₹436", "₹342", "₹456", "₹330"], "answer": 2, "explanation": "PMJJBY costs ₹436 and PMSBY ₹20 a year (both revised in June 2022), so the total is ₹456. ₹342 (₹330 + ₹12) was the total before the revision.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-36", "question": "How many of these statements about Ayushman Bharat – PM-JAY are correct? I. It was launched in September 2018 from Ranchi. II. It covers up to ₹5 lakh per family per year for secondary and tertiary hospitalisation. III. It is implemented by the National Health Authority. IV. It covers routine OPD consultations at any private clinic.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: PM-JAY covers hospitalisation, including pre- and post-hospitalisation expenses, not routine outpatient visits.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · State PSC"},
  {"id": "eco-sectors-schemes-37", "question": "Arrange these core industries in descending order of their weight in the Index of Eight Core Industries (base 2011-12): 1. Coal 2. Electricity 3. Steel 4. Refinery products", "options": ["4, 3, 2, 1", "4, 2, 3, 1", "2, 4, 3, 1", "4, 2, 1, 3"], "answer": 1, "explanation": "Refinery products 28.04%, electricity 19.85%, steel 17.92%, coal 10.33%. Order: 4, 2, 3, 1.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-38", "question": "How many of these activities belong to the tertiary sector? Banking, Transport, Construction, Mining", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Banking and transport are services (tertiary). Construction is part of the secondary (industry) sector and mining is primary. So only two.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-39", "question": "The PM Surya Ghar Muft Bijli Yojana, launched in 2024, aims at rooftop solar for how many households, with up to how many free units of electricity a month?", "options": ["1 crore households, 300 units", "1 crore households, 200 units", "5 crore households, 100 units", "10 crore households, 300 units"], "answer": 0, "explanation": "The scheme of the Ministry of New and Renewable Energy targets 1 crore households, giving up to 300 units a month of free electricity through subsidised rooftop solar panels.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-40", "question": "How many of these statements about PM Vishwakarma (2023) are correct? I. It was launched on 17 September 2023. II. It covers artisans in 18 traditional trades. III. Collateral-free credit of up to ₹3 lakh is given in two tranches. IV. The loans carry a concessional interest rate of 5%.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct: launched on Vishwakarma Jayanti, 18 trades (such as carpenters, blacksmiths, potters and tailors), ₹1 lakh followed by ₹2 lakh, at 5% interest.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · State PSC"},
  {"id": "eco-sectors-schemes-41", "question": "Which of these activities belongs to the primary sector of the economy?", "options": ["Fishing", "Banking", "Making sugar in a mill", "Writing software"], "answer": 0, "explanation": "The primary sector directly uses natural resources: farming, fishing, forestry and mining. Sugar milling is secondary (manufacturing); banking and software are tertiary (services).", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-42", "question": "Turning sugarcane into sugar in a factory is an activity of the:", "options": ["Primary sector", "Secondary sector", "Tertiary sector", "Informal service sector"], "answer": 1, "explanation": "The secondary (industrial) sector transforms raw materials into goods through manufacturing. Growing the cane is primary; selling or transporting the sugar is tertiary.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-43", "question": "The tertiary sector of the economy is also known as the:", "options": ["Industrial sector", "Agricultural sector", "Service sector", "Extractive sector"], "answer": 2, "explanation": "The tertiary sector produces services rather than goods: trade, transport, banking, communication, health, education and so on.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-44", "question": "Eight members of a family work on a small farm that needs only five people. The extra three are an example of:", "options": ["Seasonal unemployment", "Frictional unemployment", "Open unemployment", "Disguised unemployment"], "answer": 3, "explanation": "In disguised unemployment people appear to be working, but their marginal contribution is nearly zero: output would not fall if they left. It is common in Indian agriculture.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-sectors-schemes-45", "question": "Farm labourers who find work only during sowing and harvesting, and sit idle for the rest of the year, face:", "options": ["Seasonal unemployment", "Structural unemployment", "Disguised unemployment", "Cyclical unemployment"], "answer": 0, "explanation": "Seasonal unemployment arises because some activities, like rain-fed farming, need labour only in certain months. Structural unemployment comes from a long-term mismatch between skills and jobs.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-sectors-schemes-46", "question": "Which feature best distinguishes organised-sector employment from unorganised-sector employment?", "options": ["It is found only in villages", "It is registered with the government and follows rules on wages, working hours and social security", "It always pays piece rates", "It is never run by private firms"], "answer": 1, "explanation": "Organised-sector enterprises are registered and must follow laws such as the Factories Act, giving regular jobs, paid leave and provident fund. Private firms can be organised too.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-sectors-schemes-47", "question": "Indian Railways, which is owned and run by the government, is an example of the:", "options": ["Private sector", "Joint sector", "Public sector", "Cooperative sector"], "answer": 2, "explanation": "When the government owns most assets and provides the service, the enterprise is in the public sector. A joint sector unit has both government and private ownership.", "difficulty": "moderate", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-48", "question": "The “JAM trinity” used to deliver benefits directly to people refers to:", "options": ["Jobs, Agriculture, Manufacturing", "Jan Aushadhi, Ayushman, MGNREGA", "Jute, Apparel, Machinery", "Jan Dhan accounts, Aadhaar and Mobile numbers"], "answer": 3, "explanation": "Linking Jan Dhan bank accounts, Aadhaar identity and mobile phones lets the government credit subsidies straight to beneficiaries and confirm their identity, cutting out intermediaries.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-49", "question": "The main aim of Direct Benefit Transfer (DBT) is to:", "options": ["Reduce leakages by crediting benefits directly to beneficiaries' bank accounts", "Raise income-tax rates", "Replace all subsidies with loans", "Give benefits only in kind through shops"], "answer": 0, "explanation": "DBT sends cash benefits straight to Aadhaar-seeded bank accounts, removing middlemen and fake beneficiaries. It complements, not abolishes, in-kind support like PDS grain.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-50", "question": "The National Food Security Act, 2013 provides for coverage of up to:", "options": ["50% of the rural and 75% of the urban population", "75% of the rural and 50% of the urban population", "100% of the population", "Only families below the poverty line in rural areas"], "answer": 1, "explanation": "The Act covers up to 75% of rural and 50% of urban people, about two-thirds of the population, through Antyodaya and priority households. The reversed percentages are the usual trap.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-sectors-schemes-51", "question": "Under the National Food Security Act, 2013, a priority household is entitled to how much subsidised foodgrain, while an Antyodaya household gets a fixed amount per family?", "options": ["10 kg per family per month", "35 kg per person per month", "5 kg per person per month", "2 kg per person per week"], "answer": 2, "explanation": "Priority households get 5 kg per person per month; Antyodaya Anna Yojana households, the poorest, get 35 kg per household per month. Mixing up per-person and per-household is the trap.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-sectors-schemes-52", "question": "The One Nation One Ration Card system allows:", "options": ["Every citizen to get free grain without a ration card", "Only one ration card per state", "Ration cards to be used as identity for voting", "NFSA beneficiaries to draw their entitled ration from any fair price shop in the country"], "answer": 3, "explanation": "Through biometric authentication at ePoS machines, a ration card is portable, which helps migrant workers draw grain wherever they live while their family uses the same card at home.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-sectors-schemes-53", "question": "Under MGNREGA, if work is provided beyond a radius of 5 km from the worker's village, the worker is entitled to:", "options": ["Extra wages of 10% of the wage rate", "Free transport only", "Double wages", "Nothing extra, as distance does not matter"], "answer": 0, "explanation": "The Act's Schedule II says work should normally be within 5 km; if it is farther, it must be within the block and the worker gets 10% extra wages to cover travel and living costs.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-sectors-schemes-54", "question": "MGNREGA requires that, as far as possible, women make up at least what share of the beneficiaries?", "options": ["One-half", "One-third", "One-fourth", "One-tenth"], "answer": 1, "explanation": "The Act gives priority to women so that at least one-third of beneficiaries are women who have registered and asked for work. In practice women's share of person-days has often been higher.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-sectors-schemes-55", "question": "Under MGNREGA, the social audit of all works taken up in a Gram Panchayat is carried out by the:", "options": ["Comptroller and Auditor General", "District Collector", "Gram Sabha", "State Election Commission"], "answer": 2, "explanation": "Section 17 makes the Gram Sabha responsible for monitoring works and conducting regular social audits, so villagers themselves can check muster rolls and spending.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-sectors-schemes-56", "question": "For works taken up by a Gram Panchayat under MGNREGA, the ratio of wage cost to material cost must be at least:", "options": ["40:60", "50:50", "75:25", "60:40"], "answer": 3, "explanation": "The Act caps the material component at 40% at the Gram Panchayat level so that most spending goes into wages for unskilled labour, which is the purpose of the scheme.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-sectors-schemes-57", "question": "Activities centred on research, information and knowledge, such as R&D, data processing and consulting, are often grouped as the:", "options": ["Quaternary sector", "Primary sector", "Secondary sector", "Informal sector"], "answer": 0, "explanation": "Geographers split services further: the quaternary sector covers knowledge-based work, and the quinary sector covers top-level decision-makers in government and business.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-sectors-schemes-58", "question": "Kudumbashree, launched in 1998, is a poverty-eradication and women's empowerment programme of which state, organised around neighbourhood groups of women?", "options": ["Tamil Nadu", "Kerala", "Andhra Pradesh", "Gujarat"], "answer": 1, "explanation": "Kerala's Kudumbashree works through a three-tier structure of neighbourhood groups, area development societies and community development societies linked to local governments.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-sectors-schemes-59", "question": "The Self-Help Group–Bank Linkage Programme, which lets banks lend to informal groups of poor people, was launched in 1992 by:", "options": ["SIDBI", "The State Bank of India", "NABARD", "The Ministry of Finance's Department of Revenue"], "answer": 2, "explanation": "NABARD's pilot of 1992 grew into one of the world's largest microfinance programmes, with banks lending to SHGs on the basis of their savings and group guarantee rather than collateral.", "difficulty": "hard", "source": "IBPS PO · SBI PO · NABARD Grade A"},
  {"id": "eco-sectors-schemes-60", "question": "The National Rural Livelihoods Mission (Aajeevika), launched in 2011, reaches poor rural households mainly by:", "options": ["Giving them land titles", "Building rural roads", "Providing free housing", "Organising women into self-help groups and their federations"], "answer": 3, "explanation": "Now called DAY-NRLM under the Ministry of Rural Development, it mobilises one woman from each poor household into SHGs, then links them to bank credit and livelihoods.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-sectors-schemes-61", "question": "Bharatmala Pariyojana is mainly a programme for:", "options": ["Developing highways, including economic corridors and border roads", "Linking rivers", "Developing ports and coastal shipping", "Building rural broadband"], "answer": 0, "explanation": "Bharatmala focuses on national highways: economic corridors, inter-corridor and feeder routes, border and international connectivity roads. Port-led development is Sagarmala.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-sectors-schemes-62", "question": "Under a Production Linked Incentive (PLI) scheme, the incentive given to a manufacturer is generally linked to its:", "options": ["Number of employees on the rolls", "Incremental sales of goods made in India over a base year", "Imports of finished goods", "Land holdings"], "answer": 1, "explanation": "PLI schemes pay a percentage of additional sales of domestically manufactured products above a base year, rewarding firms that scale up production in India.", "difficulty": "hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-sectors-schemes-63", "question": "The Government e-Marketplace (GeM), launched in 2016, is an online platform for:", "options": ["Farmers to sell crops in mandis", "Trading government bonds", "Public procurement of goods and services by government departments and agencies", "Filing GST returns"], "answer": 2, "explanation": "GeM, under the Ministry of Commerce and Industry, lets ministries and public bodies buy from registered sellers transparently. Online crop trading is e-NAM.", "difficulty": "hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-sectors-schemes-64", "question": "For trade operations, duties and tariffs, a Special Economic Zone in India is treated as:", "options": ["A Union Territory", "A tax haven exempt from all laws", "A part of the nearest state's industrial area with no special status", "A territory deemed to be outside the customs territory of India"], "answer": 3, "explanation": "SEZs are deemed foreign territory for customs purposes, so goods brought in from the rest of India count as exports. All other Indian laws still apply inside them.", "difficulty": "hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-sectors-schemes-65", "question": "Under the Hybrid Annuity Model (HAM) for highway projects:", "options": ["The government pays about 40% of the project cost during construction and the rest to the developer as annuities", "The developer bears the full cost and keeps all the toll", "The government funds everything and the contractor only builds", "Foreign investors own the highway permanently"], "answer": 0, "explanation": "HAM blends EPC and BOT: the authority pays 40% during construction, the developer arranges 60%, and is repaid with interest through annuities; the authority collects the toll.", "difficulty": "hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-sectors-schemes-66", "question": "How many of these statements about highway project models are correct? I. In BOT (Toll), the private partner collects toll during the concession period. II. In EPC, the government finances the project and the contractor only designs and builds it. III. In HAM, the government pays about 40% of the cost during construction. IV. In HAM, the private developer bears the traffic (toll revenue) risk.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. In HAM the authority collects the toll and pays fixed annuities, so traffic risk stays with the government; IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-sectors-schemes-67", "question": "Match the type of unemployment with its description. A. Disguised  B. Seasonal  C. Frictional  D. Structural; 1. Temporary joblessness while moving between jobs  2. Mismatch between workers' skills and available jobs due to changes in the economy  3. More people engaged in work than required, adding nothing to output  4. Work available only in certain months of the year", "options": ["A-3, B-1, C-4, D-2", "A-3, B-4, C-2, D-1", "A-2, B-4, C-1, D-3", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "Disguised unemployment hides inside apparent work; seasonal follows the farm calendar; frictional is the short gap of job-search; structural reflects a lasting mismatch, for example when technology makes old skills obsolete.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-sectors-schemes-68", "question": "How many of these statements about the National Food Security Act, 2013 are correct? I. The eldest woman of at least 18 years is treated as the head of the household for issuing ration cards. II. Children aged six months to six years are entitled to a free meal through the local anganwadi. III. Each state is to set up a State Food Commission to monitor the Act. IV. Coverage is limited to households identified as below the poverty line in a 2011 survey.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "I, II and III are correct. Beneficiaries are identified by states within the 75% rural and 50% urban coverage under criteria they frame; the Act is not tied to a BPL list, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-sectors-schemes-69", "question": "Assertion (A): Paying the LPG subsidy through DBT reduced the diversion of subsidised cylinders to commercial use. Reason (R): Under DBT, cylinders are sold at market price and the subsidy is credited to the consumer's bank account.", "options": ["A is true but R is false", "Both A and R are true and R is the correct explanation of A", "A is false but R is true", "Both A and R are true but R is not the correct explanation of A"], "answer": 1, "explanation": "Once every cylinder carries the same market price, there is no cheap cylinder to divert to hotels or businesses; the subsidy reaches only the verified household's account.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-sectors-schemes-70", "question": "Arrange these programmes in the order they were launched: 1. MGNREGA  2. Pradhan Mantri Gram Sadak Yojana  3. National Rural Livelihoods Mission  4. Pradhan Mantri Jan Dhan Yojana", "options": ["1-2-3-4", "2-3-1-4", "2-1-3-4", "2-1-4-3"], "answer": 2, "explanation": "PMGSY began in 2000, MGNREGA came into force in 2006 (Act of 2005), NRLM was launched in 2011 and Jan Dhan in 2014.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-sectors-schemes-71", "question": "Which of these workers is most likely to be part of the unorganised sector?", "options": ["A clerk in a nationalised bank", "A teacher in a government school", "A street vendor selling vegetables", "An engineer in a public sector steel plant"], "answer": 2, "explanation": "Street vendors work in small, unregistered units with no fixed wages, paid leave or social security. The others hold regular, rule-bound organised-sector jobs.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-72", "question": "MGNREGA is implemented at the central level by the Ministry of:", "options": ["Labour and Employment", "Rural Development", "Agriculture and Farmers Welfare", "Panchayati Raj"], "answer": 1, "explanation": "The Ministry of Rural Development administers MGNREGA, with Gram Panchayats executing a large share of the works.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-73", "question": "The “Make in India” initiative, launched in 2014, mainly aims to:", "options": ["Promote India as a global manufacturing hub", "Encourage imports of consumer goods", "Raise farm subsidies", "Build village roads"], "answer": 0, "explanation": "Make in India seeks to attract investment, foster innovation and build manufacturing infrastructure so that more goods are made in India.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-sectors-schemes-74", "question": "The Beti Bachao Beti Padhao campaign was launched in January 2015 at:", "options": ["Varanasi, Uttar Pradesh", "Jaipur, Rajasthan", "Rohtak, Haryana", "Panipat, Haryana"], "answer": 3, "explanation": "It was launched at Panipat in Haryana, a state with a very low child sex ratio, to address falling sex ratio and promote girls' education.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "eco-sectors-schemes-75", "question": "PM-POSHAN, the renamed mid-day meal scheme, provides:", "options": ["Cash to mothers of newborns", "Hot cooked meals to children in government and government-aided schools", "Free grain to all adults", "Nutrition kits to pregnant women only"], "answer": 1, "explanation": "PM-POSHAN continues the mid-day meal: a cooked meal on school days for children in elementary classes of government and aided schools, improving nutrition and attendance.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "eco-sectors-schemes-76", "question": "POSHAN Abhiyaan (the National Nutrition Mission) was launched on 8 March 2018 at:", "options": ["Jhunjhunu, Rajasthan", "Ahmedabad, Gujarat", "Patna, Bihar", "Bhubaneswar, Odisha"], "answer": 0, "explanation": "The mission was launched on International Women's Day 2018 at Jhunjhunu to reduce stunting, under-nutrition, anaemia and low birth weight.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "eco-sectors-schemes-77", "question": "The Pradhan Mantri Kaushal Vikas Yojana (PMKVY) mainly provides:", "options": ["Crop insurance to farmers", "Pensions to unorganised workers", "Short-term skill training with certification to young people", "Housing loans at low interest"], "answer": 2, "explanation": "PMKVY, run by the Ministry of Skill Development and Entrepreneurship, offers industry-relevant short-term training and recognition of prior learning.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-sectors-schemes-78", "question": "Mission Indradhanush, launched in December 2014, aims to:", "options": ["Electrify every village", "Build toilets in schools", "Clean the river Ganga", "Raise full immunisation coverage of children and pregnant women"], "answer": 3, "explanation": "Named after the seven colours of the rainbow (originally seven vaccine-preventable diseases), it targets children and pregnant women left out of routine immunisation.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "eco-sectors-schemes-79", "question": "The AMRUT mission, launched in 2015, focuses mainly on:", "options": ["Water supply, sewerage and basic infrastructure in cities and towns", "Rural road connectivity", "Organic farming", "Coastal shipping"], "answer": 0, "explanation": "The Atal Mission for Rejuvenation and Urban Transformation targets urban water supply, sewerage, drainage, green spaces and non-motorised transport.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "eco-sectors-schemes-80", "question": "Disinvestment, in the Indian context, means:", "options": ["Withdrawing foreign investment from India", "Cutting the RBI's repo rate", "The government selling part or all of its shareholding in public sector enterprises", "Closing down loss-making private firms"], "answer": 2, "explanation": "Disinvestment raises resources and can improve efficiency by bringing in private shareholders. It is different from nationalisation, which moves ownership to the state.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-sectors-schemes-81", "question": "Strategic disinvestment differs from an ordinary minority stake sale because it:", "options": ["Involves only foreign buyers", "Transfers management control of the enterprise to the buyer", "Raises the government's stake", "Can be done only through the stock exchange"], "answer": 1, "explanation": "In a strategic sale the government sells a substantial block, usually 50% or more, together with management control. A minority sale keeps control with the government.", "difficulty": "hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-sectors-schemes-82", "question": "The National Agriculture Market (e-NAM) aims to:", "options": ["Fix minimum support prices", "Replace all APMC mandis with private markets", "Export farm produce directly", "Link existing APMC mandis into a unified online trading platform"], "answer": 3, "explanation": "e-NAM networks regulated mandis so that buyers anywhere can bid online, aiming at better price discovery for farmers. MSP is set separately on CACP's recommendation.", "difficulty": "hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-sectors-schemes-83", "question": "In the “Anand pattern” of dairy cooperatives spread through Operation Flood, the three tiers are:", "options": ["Village milk producers' society, district milk union, state federation", "Farmer, trader, exporter", "Panchayat, block, district", "Gram Sabha, Zila Parishad, state government"], "answer": 0, "explanation": "Milk is collected by village societies, processed by district unions and marketed by a state federation, as with Amul in Gujarat. Operation Flood (from 1970) was run by the NDDB.", "difficulty": "hard", "source": "UPSC Prelims · NABARD Grade A"},
  {"id": "eco-sectors-schemes-84", "question": "Which of the following is NOT one of the four labour codes that consolidate India's central labour laws?", "options": ["Code on Wages", "Industrial Relations Code", "Code on Social Security", "Code on Child Labour"], "answer": 3, "explanation": "The four codes are on Wages, Industrial Relations, Social Security, and Occupational Safety, Health and Working Conditions; together they subsume 29 central laws. There is no separate child-labour code.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-sectors-schemes-85", "question": "How many of these statements about the Pradhan Mantri Jan Dhan Yojana are correct? I. Accounts can be opened with zero balance. II. Account holders get a RuPay debit card with accident insurance cover. III. An overdraft facility is available to eligible account holders. IV. Only rural households may open accounts under it.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Jan Dhan aims at universal banking for every unbanked adult, urban or rural, so IV is wrong.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-sectors-schemes-86", "question": "How many of these statements about the Atal Pension Yojana are correct? I. Citizens aged 18 to 40 can join. II. It offers a guaranteed minimum monthly pension from age 60 in fixed slabs. III. After the subscriber's death the spouse receives the pension, and later the nominee gets the accumulated corpus. IV. Income-tax payers have been allowed to join since October 2022.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "I, II and III are correct. From 1 October 2022 income-tax payers are barred from joining APY, which targets unorganised-sector workers; IV reverses the rule.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-sectors-schemes-87", "question": "Match the infrastructure model with its description. A. BOT (Toll)  B. EPC  C. HAM  D. TOT; 1. Government funds the project fully; the contractor only designs and builds  2. Government pays about 40% during construction and the rest as annuities  3. Private firm builds, collects toll for the concession period, then hands the asset back  4. Existing public highways are leased for an upfront lump sum, letting the private party collect toll", "options": ["A-3, B-2, C-1, D-4", "A-3, B-1, C-2, D-4", "A-4, B-1, C-2, D-3", "A-3, B-1, C-4, D-2"], "answer": 1, "explanation": "BOT shifts financing and traffic risk to the private firm; EPC keeps both with the government; HAM splits funding 40:60; Toll-Operate-Transfer monetises highways already built.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-sectors-schemes-88", "question": "Assertion (A): Disguised unemployment is difficult to detect in official statistics. Reason (R): Those affected appear to be working, although removing them would not reduce total output.", "options": ["Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true", "Both A and R are true and R is the correct explanation of A"], "answer": 3, "explanation": "Because such workers are counted as employed on family farms or businesses, surveys record them as working; their zero marginal product is what makes the unemployment ‘disguised’.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-sectors-schemes-89", "question": "How many of these statements about classifying economic activity are correct? I. The primary/secondary/tertiary split is based on the nature of the activity. II. The organised/unorganised split is based on conditions of employment. III. The public/private split is based on ownership. IV. Construction is part of the tertiary sector.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "I, II and III are correct. Construction, like manufacturing, electricity and water supply, is part of the secondary (industry) sector, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-sectors-schemes-90", "question": "Arrange these food-security measures in the order they were introduced: 1. Antyodaya Anna Yojana  2. Targeted Public Distribution System  3. National Food Security Act  4. One Nation One Ration Card", "options": ["2-1-3-4", "1-2-3-4", "2-3-1-4", "1-3-2-4"], "answer": 0, "explanation": "TPDS replaced the universal PDS in 1997, AAY followed in December 2000 for the poorest, the NFSA came in 2013, and ration-card portability began in 2019 before covering all states.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-sectors-schemes-91", "question": "Match the programme with its main objective. A. PMGSY  B. UDAN  C. Sagarmala  D. Smart Cities Mission; 1. Port-led development and coastal shipping  2. All-weather roads to unconnected rural habitations  3. Area-based urban development using technology-driven solutions  4. Affordable regional air connectivity", "options": ["A-2, B-4, C-1, D-3", "A-2, B-1, C-4, D-3", "A-4, B-2, C-1, D-3", "A-2, B-4, C-3, D-1"], "answer": 0, "explanation": "PMGSY (2000) builds rural roads; UDAN (Ude Desh ka Aam Nagrik) subsidises regional flights; Sagarmala modernises ports and coastal logistics; the Smart Cities Mission (2015) funds area-based urban projects.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-sectors-schemes-92", "question": "How many of these statements are correct? I. SEZ units can import inputs duty-free. II. Export Oriented Units (EOUs) can be set up anywhere in India, not only inside zones. III. Kandla set up Asia's first Export Processing Zone in 1965. IV. The SEZ Act was passed in 2005.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The EPZs of the 1960s–80s were converted into SEZs from 2000, and the SEZ Act, 2005 gave the scheme a statutory basis.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-sectors-schemes-93", "question": "How many of these statements about foodgrain management are correct? I. The Food Corporation of India procures wheat and rice at the minimum support price. II. Grain for PDS is released to states at the central issue price, below its economic cost. III. Buffer stock norms are laid down for different quarters of the year. IV. Under decentralised procurement, some states procure and distribute grain themselves.", "options": ["Only two", "Only one", "All four", "Only three"], "answer": 2, "explanation": "All four are correct. The gap between the economic cost and the issue price is the food subsidy, and stocking norms are fixed for 1 April, 1 July, 1 October and 1 January.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-sectors-schemes-94", "question": "Assertion (A): The expansion of IT and business services has contributed to the growth of India's tertiary sector. Reason (R): The tertiary sector is defined as the sector producing tangible goods.", "options": ["Both A and R are true and R is the correct explanation of A", "A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "A is false but R is true"], "answer": 1, "explanation": "A is true: software and business services are services. R is false: the tertiary sector produces intangible services, while tangible goods come from the primary and secondary sectors.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-sectors-schemes-95", "question": "How many of these statements about self-help groups (SHGs) are correct? I. An SHG usually has about 10 to 20 members. II. Members save regularly and lend from the pooled savings to one another. III. Banks may lend to SHGs without demanding collateral. IV. An SHG must be registered as a company to receive bank loans.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "I, II and III are correct. SHGs are informal groups; banks lend on the strength of their savings record and peer pressure, and no company registration is needed, so IV is wrong.", "difficulty": "very-hard", "source": "IBPS PO · NABARD Grade A · State PSC"},
  {"id": "eco-sectors-schemes-96", "question": "Match the committee or commission with its subject. A. Shanta Kumar Committee  B. M.S. Swaminathan (National Commission on Farmers)  C. C. Rangarajan Expert Group  D. Ashok Dalwai Committee; 1. Measurement of poverty  2. Restructuring of the Food Corporation of India  3. Doubling farmers' income  4. Farmers' distress, including MSP at cost plus 50%", "options": ["A-2, B-4, C-3, D-1", "A-4, B-2, C-1, D-3", "A-2, B-4, C-1, D-3", "A-2, B-1, C-4, D-3"], "answer": 2, "explanation": "Shanta Kumar's panel (report 2015) reviewed the FCI; Swaminathan's commission (2004–06) recommended MSP at least 50% above the weighted cost; Rangarajan (2014) re-estimated poverty; Dalwai's committee drafted the strategy for doubling farmers' income.", "difficulty": "very-hard", "source": "UPSC Prelims · NABARD Grade A"},
  {"id": "eco-sectors-schemes-97", "question": "How many of these statements about cooperatives in India are correct? I. A separate Union Ministry of Cooperation was created in 2021. II. The 97th Constitutional Amendment added the right to form cooperative societies to Article 19(1)(c). III. Cooperative societies are a subject in the State List. IV. In 2021 the Supreme Court upheld Part IXB of the Constitution in full, including for state cooperative societies.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The Supreme Court struck down the provisions of Part IXB relating to state cooperatives for want of ratification by the states, keeping it only for multi-state societies, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-sectors-schemes-98", "question": "How many of these statements about the Pradhan Mantri Gram Sadak Yojana are correct? I. It was launched in 2000. II. It aims to connect eligible unconnected rural habitations with all-weather roads. III. In hill and special areas, smaller habitations qualify than in the plains. IV. It mainly funds roads inside large cities.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "I, II and III are correct; the habitation-size threshold was 500 in the plains and 250 in hill, desert and tribal areas. PMGSY is a rural scheme, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-sectors-schemes-99", "question": "Assertion (A): MGNREGA is described as largely self-targeting. Reason (R): It offers unskilled manual work at the statutory wage, so mainly those who need the work ask for it.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Because the work is physically demanding and pays only the notified wage, better-off households rarely apply, so the scheme screens itself without a beneficiary list.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-sectors-schemes-100", "question": "Match the scheme with its main target group. A. PM-POSHAN  B. POSHAN Abhiyaan  C. Antyodaya Anna Yojana  D. Atal Pension Yojana; 1. The poorest of the poor households  2. Workers in the unorganised sector  3. Schoolchildren  4. Children under six, pregnant women and lactating mothers", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "PM-POSHAN feeds schoolchildren; POSHAN Abhiyaan targets early childhood and maternal nutrition; AAY gives the poorest households 35 kg of grain; APY offers pensions to unorganised workers.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id":"eco-sectors-schemes-101","question":"According to the Clark–Fisher model of economic development, as an economy develops:","options":["the share of the primary sector in output and employment keeps rising","the main share of output and employment shifts from the primary to the secondary and then to the tertiary sector","the tertiary sector grows first and manufacturing grows last","all three sectors keep constant shares"],"answer":1,"explanation":"Rising incomes and productivity release labour from farming, first into industry and then into services. India is often cited as an exception, with services growing fast while agriculture still employs a large share of workers.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-102","question":"'Quinary' activities, sometimes called gold-collar work, are associated with:","options":["extraction of raw materials from nature","processing of raw materials into finished goods","the highest level of decision-making by senior executives, government officials and policy makers","retail trade and transport"],"answer":2,"explanation":"Quinary activities are a subset of services at the very top, where policy and strategy are decided; quaternary activities centre on knowledge, research and information, while extraction is primary and manufacturing secondary.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-sectors-schemes-103","question":"In a survey, out of 1,000 persons of working age, 570 are employed, 30 are without work but seeking or available for work, and 400 are neither working nor seeking work. The unemployment rate is:","options":["5%","3%","7.5%","5.3%"],"answer":0,"explanation":"Labour force = 570 + 30 = 600, so the unemployment rate = 30/600 = 5%. Dividing by all 1,000 persons gives 3%, which confuses the unemployment rate with a population ratio; the participation rate here is 60% and the worker–population ratio 57%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-sectors-schemes-104","question":"In the Periodic Labour Force Survey, how does the 'usual status' approach differ from the 'current weekly status' (CWS) approach?","options":["Usual status uses a reference period of the preceding 7 days, while CWS uses 365 days","Both use a reference period of the preceding 30 days","Usual status is used only for urban areas and CWS only for rural areas","Usual status classifies a person by activity over the preceding 365 days, while CWS classifies by activity during the preceding 7 days"],"answer":3,"explanation":"Usual status captures a person's long-term activity, while CWS reflects the last week and so picks up short-term and seasonal unemployment; CWS unemployment rates are therefore generally higher.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-sectors-schemes-105","question":"Under the Open Market Sale Scheme (Domestic), the Food Corporation of India:","options":["buys wheat and rice from farmers at the minimum support price","sells wheat and rice from the central pool in the open market at predetermined prices to increase supply and moderate prices","exports surplus foodgrains to neighbouring countries","distributes free grain to priority households"],"answer":1,"explanation":"OMSS offloads surplus stocks, mainly to bulk buyers such as flour mills, when market prices are high; purchase at MSP is procurement, and free grain under the NFSA reaches households through the PDS.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-sectors-schemes-106","question":"The Price Stabilisation Fund operated by the Centre is meant to:","options":["build buffer stocks of volatile commodities such as pulses and onion, buying when prices are low and releasing stocks when prices rise","pay the minimum support price for wheat","compensate exporters for swings in the rupee","subsidise the price of fertilisers"],"answer":0,"explanation":"The fund finances procurement and storage of perishable or volatile items so that releases can damp price spikes for consumers while protecting farmers from distress sales.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-107","question":"Under the Decentralised Procurement (DCP) system for foodgrains:","options":["only the Food Corporation of India procures grain in all states","private traders procure grain on behalf of the Centre","State governments themselves procure, store and distribute foodgrains for the NFSA and welfare schemes, with the Centre meeting the approved costs","the system applies only to pulses and oilseeds"],"answer":2,"explanation":"DCP, begun in 1997–98, lets states buy grain locally at MSP and use it directly, cutting transport costs and widening procurement to more states; any surplus is handed to the FCI for the central pool.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-sectors-schemes-108","question":"The Industrial Policy Resolution of 1956 classified industries into:","options":["three schedules: industries reserved exclusively for the State, industries to be progressively State-owned in which private enterprise could also take part, and the rest left mainly to the private sector","only two lists, public and private","a short list of industries needing licences, with licensing abolished for all others","industries to be fully privatised within ten years"],"answer":0,"explanation":"The 1956 Resolution (Schedules A, B and C) gave the public sector the 'commanding heights'. Abolition of licensing for most industries came with the 1991 New Industrial Policy, the trap here.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-109","question":"Viability Gap Funding (VGF) for infrastructure projects under public–private partnership is:","options":["a loan to State governments to balance their budgets","a capital grant from the government that makes an economically justified but commercially unviable project attractive to private investors","a tax holiday for all private infrastructure firms","a penalty on private partners for delays"],"answer":1,"explanation":"Projects such as roads in remote areas may yield high social returns but low revenue; VGF bridges the gap, usually awarded to the bidder seeking the least grant.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-sectors-schemes-110","question":"The PM Gati Shakti National Master Plan, launched in 2021, is mainly:","options":["a new expressway linking Delhi and Mumbai","a freight subsidy for exporters","a GIS-based digital platform bringing ministries such as railways and road transport together for integrated planning and coordinated execution of infrastructure","a high-speed rail project"],"answer":2,"explanation":"Gati Shakti layers data on existing and planned assets so that projects across ministries can be planned together, cutting delays and logistics costs; it is a planning tool, not a single project.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-111","question":"Farmer Producer Organisations (FPOs) are best described as:","options":["government agencies that procure grain at MSP","private firms that undertake contract farming","branches of NABARD in rural areas","collectives of farmers, registered as producer companies or cooperatives, that pool produce and buy inputs together to gain bargaining power"],"answer":3,"explanation":"By aggregating small and marginal farmers, FPOs gain economies of scale in buying inputs, accessing credit and selling produce; NABARD and SFAC only promote and support them.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-112","question":"Consider the following statements: I. Payments banks can accept deposits but cannot lend. II. Small finance banks can accept deposits and lend, with a focus on unserved and underserved sections. III. Payments banks can issue credit cards to their customers. Which of the statements given above is/are correct?","options":["I only","I and II only","II and III only","I, II and III"],"answer":1,"explanation":"Payments banks can offer deposits, remittances and debit cards, but since they cannot lend they cannot issue credit cards, so III is wrong. Both types were created after the Nachiket Mor Committee's report to deepen financial inclusion.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-113","question":"The share capital of a Regional Rural Bank is held by the Central Government, the sponsor bank and the State Government in the ratio:","options":["50 : 35 : 15","50 : 15 : 35","35 : 50 : 15","40 : 40 : 20"],"answer":0,"explanation":"The Centre holds half, the sponsor bank 35% and the State 15%. RRBs, set up from 1975, combine local feel with commercial banking discipline to serve small farmers, labourers and artisans.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-114","question":"Match the institution with its main role. A. NABARD  B. SIDBI  C. National Housing Bank  D. EXIM Bank; 1. Refinance and promotion of housing finance  2. Financing of foreign trade  3. Apex institution for agriculture and rural development credit  4. Principal institution for financing and promoting MSMEs","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"NABARD (1982) refinances rural credit, SIDBI (1990) serves small industry, the NHB (1988) supports housing finance and the EXIM Bank (1982) finances exports and imports.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-115","question":"Which labour code, for the first time in Indian law, defines 'gig workers' and 'platform workers' and provides for social security schemes for them?","options":["Code on Wages, 2019","Industrial Relations Code, 2020","Code on Social Security, 2020","Occupational Safety, Health and Working Conditions Code, 2020"],"answer":2,"explanation":"The Code on Social Security brings gig and platform workers, who fall outside the traditional employer–employee relationship, under schemes that may be funded partly by contributions from aggregators.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-sectors-schemes-116","question":"NITI Aayog's National Multidimensional Poverty Index is built on which three equally weighted dimensions?","options":["Income, consumption and assets","Health, education and standard of living","Employment, income and housing","Nutrition, sanitation and electricity"],"answer":1,"explanation":"Following the global MPI, it uses health, education and standard of living (with indicators such as nutrition, schooling, sanitation and cooking fuel). Nutrition, sanitation and electricity are indicators within these dimensions, not dimensions themselves.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-sectors-schemes-117","question":"Two regions have the same head-count ratio of poverty, but the poor in Region X are on average much further below the poverty line than those in Region Y. Which measure will be higher for Region X?","options":["The head-count ratio","The Human Development Index","The literacy rate","The poverty gap index"],"answer":3,"explanation":"The head-count ratio only counts how many are poor; the poverty gap index also measures how far below the line they are, so it is higher where poverty is deeper.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-118","question":"The Human Development Index of the UNDP combines indicators of:","options":["life expectancy at birth, mean and expected years of schooling, and gross national income per capita (PPP)","infant mortality, literacy and GDP growth","life expectancy, employment and inflation","nutrition, sanitation and per capita consumption"],"answer":0,"explanation":"The HDI averages three dimensions: a long and healthy life, knowledge and a decent standard of living. GDP growth and inflation are not part of it.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-119","question":"The 'Kuznets curve' hypothesis suggests that as per capita income rises:","options":["income inequality falls steadily","income inequality first rises and then falls, tracing an inverted U","income inequality rises without limit","the share of agriculture in GDP first rises and then falls"],"answer":1,"explanation":"Kuznets argued that early industrialisation widens gaps between the modern and traditional sectors, which narrow later as labour moves and education spreads. The same inverted-U shape was later applied to pollution as the 'environmental Kuznets curve'.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-sectors-schemes-120","question":"W. Arthur Lewis's dual-sector model explains development as:","options":["export-led growth based on comparative advantage","a 'big push' of simultaneous investment in many industries","balanced growth of agriculture through new seed technology","the transfer of surplus labour from a low-productivity traditional, largely agricultural sector to a modern industrial sector at a near-constant wage, with profits reinvested"],"answer":3,"explanation":"In Lewis's model the modern sector can expand without raising wages as long as surplus labour lasts, and reinvested profits drive growth. The 'big push' is Rosenstein-Rodan's idea.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-121","question":"In a year, gross value added (GVA) at basic prices is ₹250 lakh crore, product taxes are ₹30 lakh crore and product subsidies ₹10 lakh crore. GDP at market prices is:","options":["₹290 lakh crore","₹250 lakh crore","₹270 lakh crore","₹230 lakh crore"],"answer":2,"explanation":"GDP = GVA at basic prices + product taxes − product subsidies = 250 + 30 − 10 = 270. Adding the subsidies (290) or ignoring the taxes (230) are the common slips.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-sectors-schemes-122","question":"The Rural Infrastructure Development Fund (RIDF), operated by NABARD since 1995–96, gets its money mainly from:","options":["a cess on agricultural exports","direct budgetary grants to farmers","loans from the World Bank","deposits placed by commercial banks that fall short of their priority-sector lending targets"],"answer":3,"explanation":"Banks that miss their agriculture or priority-sector targets must deposit the shortfall in RIDF and similar funds; NABARD lends this money to States for rural roads, irrigation and other infrastructure.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-123","question":"A 'demographic dividend' becomes available to an economy when:","options":["the population starts to shrink","the death rate rises above the birth rate","the share of the working-age population rises relative to dependent children and elderly people","the share of elderly people in the population rises sharply"],"answer":2,"explanation":"A falling dependency ratio frees resources for saving and investment and enlarges the labour force; the dividend is realised only if these workers are healthy, skilled and productively employed. An ageing population reverses it.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-124","question":"In a district, 2,000 people are aged 15 and above: 1,000 are employed, 100 are without work but seeking or available for it, and the rest are outside the labour force. Which set of indicators is correct?","options":["LFPR 55%, WPR 50%, unemployment rate 5.0%","LFPR 50%, WPR 55%, unemployment rate 9.1%","LFPR 55%, WPR 50%, unemployment rate 9.1%","LFPR 55%, WPR 45%, unemployment rate 10.0%"],"answer":2,"explanation":"LFPR = 1,100/2,000 = 55%; WPR = 1,000/2,000 = 50%; the unemployment rate is measured against the labour force, 100/1,100 ≈ 9.1%. Dividing by the whole population gives the wrong 5%.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-125","question":"Under the usual principal and subsidiary status (UPSS) approach of the PLFS, a person whose main activity in the past year was not work is still counted as employed if he or she worked in a subsidiary capacity for at least:","options":["15 days","30 days","60 days","183 days"],"answer":1,"explanation":"Usual principal status uses the activity of the major part of the year (183 days or more); a person outside work on that basis is added to the workforce if engaged in subsidiary work for 30 days or more.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-126","question":"Which approach to measuring unemployment usually gives the highest unemployment rate, because it records joblessness on individual days within a week?","options":["Usual principal status","Usual principal and subsidiary status","Current weekly status","Current daily status"],"answer":3,"explanation":"Current daily status counts person-days, so a worker who finds work on only some days of the week is partly unemployed. Usual status takes a whole-year view and gives the lowest rate.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-127","question":"As first designed in 2017, the Periodic Labour Force Survey of the NSO gave quarterly estimates of labour-force indicators in current weekly status for:","options":["Rural areas only","Both rural and urban areas","Urban areas only","Only the organised sector"],"answer":2,"explanation":"The PLFS replaced the five-yearly employment–unemployment rounds; it gave quarterly CWS estimates for urban areas and annual estimates, in both usual and weekly status, for rural and urban areas together.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-128","question":"A software tester loses her job because testing is now done by automated tools, and she lacks the skills that the new jobs need. This is best described as:","options":["Frictional unemployment","Cyclical (demand-deficient) unemployment","Disguised unemployment","Technological unemployment"],"answer":3,"explanation":"Unemployment caused by labour-saving technology, which leaves workers’ skills mismatched with new jobs, is technological (a form of structural) unemployment. Frictional unemployment is the short gap while changing jobs.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-129","question":"After successive dereservations following the 1991 industrial policy, which areas remain reserved exclusively for the public sector?","options":["Atomic energy and railway operations","Defence production and railway operations","Atomic energy and coal mining","Railway operations and civil aviation"],"answer":0,"explanation":"The 1991 policy cut the reserved list from 17 industries to 8, and later changes left only atomic energy (with specified minerals) and railway operations. Coal and defence were opened to private players.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-130","question":"Which of these industries still needs a compulsory industrial licence in India?","options":["Manufacture of passenger cars and utility vehicles","Manufacture of Portland cement and clinker","Manufacture of finished and alloy steel","Manufacture of cigars and cigarettes of tobacco"],"answer":3,"explanation":"Compulsory licensing now covers only a few industries for health, safety or strategic reasons: alcoholic drinks, tobacco cigars and cigarettes, electronic aerospace and defence equipment, industrial explosives and hazardous chemicals.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-131","question":"The Monopolies and Restrictive Trade Practices (MRTP) Act, 1969 was replaced by the:","options":["Competition Act, 2002","Consumer Protection Act, 1986","Industries (Development and Regulation) Act, 1951","Foreign Exchange Management Act, 1999"],"answer":0,"explanation":"The Competition Act, 2002, administered by the Competition Commission of India, shifted the focus from curbing big business to preventing anti-competitive conduct and abuse of dominance.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-132","question":"A key difference between the Foreign Exchange Management Act, 1999 and the FERA it replaced is that under FEMA, violations are:","options":["Criminal offences tried only by special economic courts","Civil offences, dealt with mainly through monetary penalties","Settled only by the RBI, with no right of appeal at all","Cognisable offences punishable under the Indian Penal Code"],"answer":1,"explanation":"FERA (1973) aimed at conserving scarce foreign exchange and treated violations as criminal; FEMA aims at facilitating external trade and payments, treating most contraventions as civil matters with penalties.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-133","question":"To be considered for Navratna status, a central public sector enterprise must first be:","options":["A listed company with at least 25% of its shares held by the public","A Maharatna company that has slipped below the Maharatna criteria","A Miniratna Category-I, Schedule ‘A’ CPSE with good MoU ratings","Any profit-making CPSE with a positive net worth for three years"],"answer":2,"explanation":"Navratna status is open to Miniratna Category-I, Schedule ‘A’ CPSEs with ‘excellent’ or ‘very good’ MoU ratings in three of the last five years and a qualifying score on performance indicators. Maharatna is the higher tier.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-134","question":"The Department of Disinvestment was renamed the Department of Investment and Public Asset Management (DIPAM) in:","options":["2014","2019","2016","2021"],"answer":2,"explanation":"The 2016 renaming, with DIPAM under the Finance Ministry, reflected a wider remit covering management of the government’s equity, not just stake sales.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-sectors-schemes-135","question":"Under the New Public Sector Enterprise Policy announced in 2021, in the designated strategic sectors the government will:","options":["Keep all existing CPSEs and set up new ones to expand public presence","Exit fully by selling every enterprise in these sectors to private buyers","Retain all CPSEs but list every one of them on the stock exchanges","Keep a bare minimum presence and privatise, merge or close the other CPSEs"],"answer":3,"explanation":"For the four broad strategic sectors the policy keeps a minimum public presence; in non-strategic sectors CPSEs are to be privatised or closed where feasible.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-136","question":"The monthly Index of Eight Core Industries is compiled and released by:","options":["The National Statistics Office under MoSPI","The Office of the Economic Adviser, DPIIT","The Reserve Bank of India","The Central Electricity Authority"],"answer":1,"explanation":"The Office of the Economic Adviser in DPIIT (Commerce and Industry Ministry) releases the core index, which is also a lead indicator for the IIP. The IIP itself is compiled by the NSO.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-sectors-schemes-137","question":"Which of the following is NOT a use-based category of the Index of Industrial Production?","options":["Infrastructure/construction goods","Consumer durables","Intermediate goods","Basic metals"],"answer":3,"explanation":"The use-based groups are primary, capital, intermediate, infrastructure/construction, consumer durable and consumer non-durable goods. Basic metals is an industry group under the sectoral (NIC) classification.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-138","question":"Under the MSMED Act, 2006, if a buyer fails to pay a micro or small supplier within the agreed period (which cannot exceed 45 days), the buyer must pay:","options":["Simple interest at the RBI’s bank rate for the period of delay","Compound interest with monthly rests at three times the bank rate","Simple interest at the repo rate plus two percentage points","A flat penalty of 10% of the amount due, payable once"],"answer":1,"explanation":"Sections 15 and 16 of the MSMED Act cap the credit period at 45 days and impose compound interest at three times the RBI’s bank rate, with monthly rests, on delayed payments, to protect small suppliers’ cash flows.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-139","question":"The Trade Receivables electronic Discounting System (TReDS) helps MSMEs mainly by:","options":["Giving them collateral-free term loans at a fixed concessional rate","Letting financiers bid to discount their invoices raised on large buyers","Guaranteeing their exports against non-payment by foreign buyers","Allowing them to list their shares on a special SME exchange"],"answer":1,"explanation":"On TReDS platforms set up under RBI guidelines, an MSME’s invoices accepted by corporate or government buyers are auctioned to banks and NBFCs, so the seller is paid early without recourse to it.","difficulty":"hard","source":"RBI Grade B"},
  {"id":"eco-sectors-schemes-140","question":"The Credit Guarantee Fund Trust for Micro and Small Enterprises, which backs collateral-free loans to such units, was set up in 2000 by the Government of India and:","options":["NABARD","The Reserve Bank of India","SIDBI","State Bank of India"],"answer":2,"explanation":"CGTMSE was set up jointly by the Government of India (Ministry of MSME) and SIDBI; it guarantees a large part of loans given without collateral or third-party guarantee to micro and small enterprises.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-141","question":"The Prime Minister’s Employment Generation Programme (PMEGP), formed in 2008 by merging PMRY and REGP, is implemented at the national level by:","options":["SIDBI","NABARD","The National Skill Development Corporation (NSDC)","The Khadi and Village Industries Commission"],"answer":3,"explanation":"PMEGP is a credit-linked subsidy scheme of the MSME Ministry for setting up micro enterprises; KVIC is the national nodal agency, working with State KVIBs and District Industries Centres.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-sectors-schemes-142","question":"‘Udyam Registration’, introduced on 1 July 2020 for micro, small and medium enterprises, replaced the:","options":["Udyog Aadhaar Memorandum","Shops and Establishments licence","GST registration","Factories Act licence"],"answer":0,"explanation":"Udyam Registration is an online, paperless, self-declaration system linked to PAN and GST data; it replaced the Udyog Aadhaar Memorandum and uses the revised investment-plus-turnover criteria.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-143","question":"In India’s Agriculture Census, an operational holding of 3 hectares falls in which size class?","options":["Small","Semi-medium","Medium","Marginal"],"answer":1,"explanation":"The classes are marginal (below 1 ha), small (1–2 ha), semi-medium (2–4 ha), medium (4–10 ha) and large (10 ha and above), so 3 ha is semi-medium. Marginal and small together form the great majority of holdings.","difficulty":"very-hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-144","question":"How many of these statements are correct? I. The Commission for Agricultural Costs and Prices is a statutory body. II. MSPs for kharif and rabi crops are announced by the Government after considering CACP’s recommendations. III. The fair and remunerative price of sugarcane is fixed under the Sugarcane (Control) Order, 1966. IV. MSP is legally enforceable, so private traders must buy at or above it.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and III are correct. CACP is an attached office of the Agriculture Ministry, not a statutory body, and MSP is a policy price used for government procurement with no legal force on private trade.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-145","question":"In CACP cost concepts, cost C2 differs from cost A2+FL mainly because C2 also includes:","options":["The imputed value of the unpaid labour of family members","Paid-out costs on seeds, fertilisers and hired labour","Rent on owned land and interest on owned fixed capital","Depreciation on implements and farm buildings"],"answer":2,"explanation":"A2 covers paid-out costs (including depreciation), A2+FL adds unpaid family labour, and C2 further adds imputed rent on owned land and interest on owned capital, making it the most comprehensive cost.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-146","question":"Since 2018–19, the Centre has fixed the MSPs of mandated crops at a level of at least 1.5 times the:","options":["A2 cost","A2+FL cost","C2 cost","B2 cost"],"answer":1,"explanation":"The 2018–19 Budget promised MSP of at least one and a half times the cost of production, and the cost used is A2+FL. The National Commission on Farmers had recommended 1.5 times the C2 cost.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-147","question":"Match the ‘revolution’ with its product: A. Yellow  B. Blue  C. White  D. Round; 1. Milk  2. Potato  3. Oilseeds  4. Fish","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-1, B-4, C-3, D-2"],"answer":2,"explanation":"The Yellow Revolution was in oilseeds, the Blue in fisheries, the White in milk (Operation Flood) and the Round in potatoes.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-148","question":"Operation Flood, launched in 1970 to create a national milk grid linking producers with urban consumers, was implemented by:","options":["The National Dairy Development Board","Amul (Kaira District Co-operative Milk Producers’ Union)","NABARD","The Ministry of Food Processing Industries"],"answer":0,"explanation":"NDDB, headed by Verghese Kurien, ran Operation Flood in three phases up to 1996, replicating the Anand-pattern cooperatives across the country. Amul was the model, not the implementing agency.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-149","question":"The Technology Mission on Oilseeds (1986), which drove the ‘Yellow Revolution’, is associated with:","options":["M. S. Swaminathan","Verghese Kurien","Sam Pitroda","Norman Borlaug"],"answer":2,"explanation":"The Technology Mission on Oilseeds was one of the technology missions under Rajiv Gandhi led by Sam Pitroda. Swaminathan and Borlaug are linked with the Green Revolution, Kurien with the White Revolution.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-150","question":"Assertion (A): The early gains of the Green Revolution were concentrated mainly in wheat in the irrigated north-west of India. Reason (R): The high-yielding varieties needed assured irrigation and heavy use of fertilisers.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"HYV seeds paid off only with assured water and inputs, which Punjab, Haryana and western Uttar Pradesh had; this widened regional and crop disparities, with rice and rain-fed areas gaining later.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-151","question":"‘Per Drop More Crop’, which promotes micro-irrigation such as drip and sprinklers, is a component of:","options":["Pradhan Mantri Krishi Sinchayee Yojana","Mission for Integrated Development of Horticulture","Paramparagat Krishi Vikas Yojana","Pradhan Mantri Fasal Bima Yojana"],"answer":0,"explanation":"PMKSY, launched in 2015, has components such as ‘Har Khet Ko Pani’ (expanding irrigation) and ‘Per Drop More Crop’ (water-use efficiency at the farm).","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-152","question":"The Paramparagat Krishi Vikas Yojana, launched in 2015, mainly promotes:","options":["Organic farming through clusters of farmers with group certification","Crop insurance for traditional rice and millet varieties at low premium","Revival of old village irrigation tanks through the gram panchayats","Traditional handloom and handicraft clusters in rural districts"],"answer":0,"explanation":"PKVY organises farmers into clusters to take up organic farming, supports inputs and marketing, and uses the Participatory Guarantee System (PGS-India) for certification.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-153","question":"The Agriculture Infrastructure Fund, set up in 2020, mainly provides:","options":["Direct cash transfers to farmers for buying tractors and machinery","Grants to the States for building new APMC mandi yards and roads","Equity capital to agri-startups through a dedicated fund of funds","Subsidised, guaranteed loans for post-harvest and community farm assets"],"answer":3,"explanation":"The ₹1 lakh crore financing facility gives 3% interest subvention and credit guarantee cover on loans up to ₹2 crore for warehouses, cold chains, processing units and similar assets.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-154","question":"Operation Greens, announced in 2018 under the Ministry of Food Processing Industries, initially aimed to stabilise the supply and prices of:","options":["Pulses, oilseeds and maize","Wheat, rice and coarse cereals","Milk, eggs and fish","Tomato, onion and potato"],"answer":3,"explanation":"Modelled on Operation Flood, it began with the ‘TOP’ crops, whose prices swing sharply; in 2020 it was extended to other fruits and vegetables.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-155","question":"The e-Shram portal, launched in 2021, is meant to:","options":["Build an Aadhaar-linked national database of unorganised workers","Register start-ups for tax benefits under the Startup India scheme","Pay MGNREGA wages directly into the bank accounts of workers","Match young graduates with apprenticeship places in industry"],"answer":0,"explanation":"Run by the Ministry of Labour and Employment, e-Shram registers unorganised workers, including migrants and gig workers, and gives each a Universal Account Number to help deliver social security benefits.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-156","question":"The Jawahar Rozgar Yojana, launched in 1989, was formed by merging:","options":["IRDP and TRYSEM","EAS and JGSY","NREP and RLEGP","SGSY and DWCRA"],"answer":2,"explanation":"JRY combined the National Rural Employment Programme (1980) and the Rural Landless Employment Guarantee Programme (1983). EAS and JGSY were later merged into SGRY in 2001.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-157","question":"Which of the following was NOT merged into the Swarnjayanti Gram Swarozgar Yojana in 1999?","options":["Integrated Rural Development Programme","Training of Rural Youth for Self-Employment","Development of Women and Children in Rural Areas","National Food for Work Programme"],"answer":3,"explanation":"SGSY brought together IRDP, TRYSEM, DWCRA, SITRA, GKY and the Million Wells Scheme as one self-employment programme. The Food for Work Programme came later (2004) and was folded into NREGA.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-158","question":"Arrange in time order: 1. Sampoorna Grameen Rozgar Yojana launched  2. NREGA comes into force in 200 districts  3. Jawahar Rozgar Yojana launched  4. National Food for Work Programme launched","options":["3, 1, 4, 2","3, 4, 1, 2","1, 3, 4, 2","3, 1, 2, 4"],"answer":0,"explanation":"JRY came in 1989, SGRY in 2001, the National Food for Work Programme in 2004, and NREGA came into force on 2 February 2006; it was renamed after Mahatma Gandhi in 2009.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-159","question":"Under MGNREGA, an applicant who is not given work within 15 days is entitled to an unemployment allowance of at least:","options":["Half the wage rate for the first 30 days and the full wage thereafter","One-fourth of the wage rate for the first 30 days and half thereafter","One-third of the wage rate throughout the rest of the financial year","The full notified wage rate from the first day of delay"],"answer":1,"explanation":"Section 7 of the Act sets the allowance at not less than one-fourth of the wage rate for the first 30 days in a financial year and not less than half for the rest of the year; it is paid by the State.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-160","question":"How many of these statements about MGNREGA are correct? I. Job cards are issued to households free of cost. II. Contractors are not allowed in carrying out the works. III. As far as practicable, works are to be done by manual labour rather than machines. IV. The Central Government notifies the wage rate for each State.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four reflect the Act: free job cards, a ban on contractors, a preference for manual labour over labour-displacing machines, and wage rates notified by the Centre under Section 6(1).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-161","question":"The National Social Assistance Programme, launched in 1995 with old age, widow and disability pensions, gives effect mainly to which Directive Principle?","options":["Article 39A","Article 43","Article 41","Article 47"],"answer":2,"explanation":"Article 41 asks the State to provide public assistance in cases of old age, sickness, disablement and undeserved want. Article 39A covers free legal aid, 43 a living wage, and 47 nutrition and public health.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-162","question":"Under the National Family Benefit Scheme, part of NSAP, assistance is given:","options":["As a monthly pension to every widow living in a BPL household","As a cash incentive to BPL families on the birth of a girl child","As a lump sum to a BPL household when its main earner dies","As free life insurance cover for all members of a BPL household"],"answer":2,"explanation":"NFBS pays a one-time lump sum to a poor household when its main earner, aged 18 to 59, dies. Widow pensions come under a separate NSAP component.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-163","question":"The Annapurna scheme provides:","options":["Free cooked midday meals to all school children up to Class VIII","Subsidised grain to Antyodaya households at a nominal token price","10 kg of free grain a month to needy elderly without a pension","Free LPG refills every month to elderly women living in villages"],"answer":2,"explanation":"Annapurna, part of NSAP since 2000, gives 10 kg of free foodgrains a month to senior citizens who qualify for an old age pension but are not receiving it.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-164","question":"Which of these is NOT one of the six services provided under the Integrated Child Development Services (ICDS) scheme?","options":["Supplementary nutrition","Pre-school non-formal education","Immunisation and health check-ups","Free secondary-school textbooks"],"answer":3,"explanation":"Since 1975, ICDS has offered supplementary nutrition, pre-school education, nutrition and health education, immunisation, health check-ups and referral services through anganwadi centres. School textbooks are not part of it.","difficulty":"very-hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-165","question":"The Janani Suraksha Yojana, launched in 2005 under the National Rural Health Mission, mainly aims to:","options":["Promote hospital births among poor mothers through cash aid","Provide free contraceptives to all married couples in villages","Insure mothers against the cost of caesarean surgery in hospitals","Give free nutrition kits to all children below six years of age"],"answer":0,"explanation":"JSY is a conditional cash transfer that rewards delivery in a health facility, to cut maternal and newborn deaths; ASHA workers help mothers reach facilities.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-166","question":"The Pradhan Mantri Matru Vandana Yojana, launched in 2017, provides:","options":["Free hospital delivery for all women in government hospitals","Monthly pensions to widows aged above 40 in poor rural households","Cash support to pregnant and lactating women for lost wages","Free sanitary products to all adolescent girls in government schools"],"answer":2,"explanation":"PMMVY is a maternity benefit scheme giving cash in instalments, mainly for the first living child, to partly compensate for wage loss and encourage health-seeking behaviour.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-167","question":"Samagra Shiksha, launched in 2018 as an integrated scheme for school education, subsumed:","options":["SSA, RMSA and Teacher Education","SSA, mid-day meals and Teacher Education","RMSA, RUSA and the National Means-cum-Merit Scheme","SSA, RUSA and Kendriya Vidyalayas"],"answer":0,"explanation":"It merged Sarva Shiksha Abhiyan, Rashtriya Madhyamik Shiksha Abhiyan and Teacher Education to treat schooling from pre-school to Class XII as a continuum. RUSA is for higher education and mid-day meals remain a separate scheme.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-168","question":"The two pillars of Ayushman Bharat, launched in 2018, are:","options":["PM-JAY and the National Health Mission","Health and Wellness Centres and PM-JAY","Jan Aushadhi Kendras and Health and Wellness Centres","PM-JAY and the Ayushman Bharat Digital Mission"],"answer":1,"explanation":"Ayushman Bharat combines Health and Wellness Centres (now Ayushman Arogya Mandirs) for comprehensive primary care with PM-JAY, which covers secondary and tertiary hospitalisation.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-169","question":"The ABHA number created under the Ayushman Bharat Digital Mission (2021) is:","options":["A card that entitles the holder to free treatment in hospitals","A health ID that links a person’s digital health records","A licence number issued to registered doctors and hospitals","A policy number for the PM-JAY hospitalisation cover"],"answer":1,"explanation":"The Ayushman Bharat Health Account is a unique health ID that lets records from different providers be linked and shared with the person’s consent; it does not itself give insurance or free care.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-170","question":"Accredited Social Health Activists (ASHAs), the community health workers in villages, were introduced under:","options":["The ICDS scheme in 1975","The National Urban Health Mission in 2013","Ayushman Bharat in 2018","The National Rural Health Mission in 2005"],"answer":3,"explanation":"NRHM created the ASHA, a trained woman volunteer from the village who links households with the health system. ICDS works through anganwadi workers, a different cadre.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-171","question":"Beneficiaries under the Pradhan Mantri Awaas Yojana – Gramin are selected mainly using:","options":["The BPL lists prepared by the States in the 2002 census of the poor","Households holding Antyodaya ration cards under the NFSA, 2013","Housing deprivation data of SECC 2011, verified by Gram Sabhas","Farmers enrolled for income support under the PM-KISAN scheme"],"answer":2,"explanation":"PMAY-G, which replaced Indira Awaas Yojana in 2016, uses the Socio-Economic and Caste Census 2011 to identify houseless and kutcha-house households, with the list validated by the Gram Sabha.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-172","question":"Under the Saansad Adarsh Gram Yojana, launched in 2014, each Member of Parliament:","options":["Gets a separate central fund to build a model village in the constituency","Adopts a gram panchayat and develops it using existing schemes","Must adopt his or her own native village and develop it as a model","Chooses villages that the Planning Commission listed as most backward"],"answer":1,"explanation":"SAGY has no separate allocation; MPs use MPLADS and existing schemes to develop a chosen gram panchayat. They may not choose their own or their spouse’s village.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-173","question":"The Shyama Prasad Mukherji Rurban Mission (2016) aims to:","options":["Develop clusters of villages with urban-like amenities","Resettle slum dwellers from cities into new rural townships","Build national highways linking district towns to villages","Merge small villages into municipal bodies of nearby towns"],"answer":0,"explanation":"The mission develops ‘Rurban’ clusters, groups of villages with growth potential, providing infrastructure and skills so they can grow without losing their rural character.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-174","question":"Deen Dayal Upadhyaya Grameen Kaushalya Yojana (2014) is:","options":["A placement-linked skilling scheme for poor rural youth under NRLM","A crop insurance scheme for tenant farmers in backward districts","A pension scheme for rural artisans aged 60 and above","A scheme for electrifying villages and separating farm feeders"],"answer":0,"explanation":"DDU-GKY, run by the Ministry of Rural Development, trains poor rural youth, mostly aged 15–35, and places them in wage jobs. Village electrification came under the similarly named DDUGJY.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-175","question":"Match the scheme with its nodal ministry: A. DDU-GKY  B. DAY-NULM  C. PMKVY  D. PM-SYM; 1. Housing and Urban Affairs  2. Labour and Employment  3. Rural Development  4. Skill Development and Entrepreneurship","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4"],"answer":0,"explanation":"DDU-GKY is a rural development scheme and DAY-NULM its urban counterpart under Housing and Urban Affairs; PMKVY belongs to the Skill Development Ministry and the PM-SYM pension scheme to Labour and Employment.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-176","question":"How many of these statements about the Pradhan Mantri Shram Yogi Maan-dhan (PM-SYM) scheme of 2019 are correct? I. Unorganised workers aged 18 to 40 can join. II. The Central Government contributes an amount equal to the worker’s contribution. III. It offers an assured pension of ₹3,000 a month from the age of 60. IV. Members of the EPFO, ESIC or NPS can also join it.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The scheme is meant for workers outside formal social security, so members of EPFO, ESIC or NPS, and income-tax payers, are excluded; IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-177","question":"Under the definition notified in 2019 for Startup India, an entity is recognised as a startup for up to how many years from incorporation, provided its turnover has not exceeded ₹100 crore in any year?","options":["5 years","7 years","15 years","10 years"],"answer":3,"explanation":"DPIIT’s 2019 notification raised the age limit to 10 years and the turnover limit to ₹100 crore; the entity must also be working on innovation or a scalable business model.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-sectors-schemes-178","question":"The Fund of Funds for Startups (2016) supports startups by:","options":["Lending directly to startups at concessional rates through banks","Investing in SEBI-registered AIFs, which in turn invest in startups","Buying shares of startups that are listed on the SME exchanges","Guaranteeing working capital loans given by NBFCs to startups"],"answer":1,"explanation":"The fund, managed by SIDBI, does not invest in startups directly; it commits capital to SEBI-registered AIFs, which then invest in startups, drawing in private money.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-179","question":"Atal Tinkering Labs, which give school students space and tools to build and experiment, are set up under:","options":["Atal Innovation Mission of NITI Aayog","Samagra Shiksha of the Education Ministry","Digital India of the IT Ministry","Startup India of DPIIT"],"answer":0,"explanation":"The Atal Innovation Mission, set up by NITI Aayog in 2016, runs Atal Tinkering Labs in schools and Atal Incubation Centres to build a culture of innovation.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-180","question":"The Delhi–Mumbai Industrial Corridor was planned along which piece of transport infrastructure?","options":["50%","25%","75%","100%"],"answer":2,"explanation":"DMIC was conceived in the late 2000s to use the high-capacity Western Dedicated Freight Corridor between Dadri and JNPT as its backbone, with new industrial cities along it.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-181","question":"The Western Dedicated Freight Corridor runs between:","options":["Ludhiana and Dankuni via Sonnagar","Sonnagar and Dankuni in the east","Delhi and Kandla Port in Gujarat","Dadri and Jawaharlal Nehru Port"],"answer":3,"explanation":"The Western DFC links Dadri in Uttar Pradesh with JNPT near Mumbai; the Eastern DFC links Ludhiana with Sonnagar, with an extension planned to Dankuni.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-182","question":"Under the UDAN regional connectivity scheme (2016), fares on routes to unserved airports are kept low mainly by:","options":["Fixing the fares of all seats on every domestic flight in India","Capping fares on some seats and giving airlines viability gap funding","Exempting the airlines on these routes from all taxes and fees","Running these flights only through the public sector Air India"],"answer":1,"explanation":"Airlines bid for routes, cap fares on a share of seats and receive viability gap funding from the Centre, States and airport operators, part of it financed by a levy on other domestic flights.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-183","question":"The UJALA scheme, implemented by Energy Efficiency Services Limited from 2015, mainly involved:","options":["Distributing LED bulbs to households at low prices","Installing solar pumps on farms with central subsidy","Providing free electricity connections to poor homes","Separating farm feeders from rural household feeders"],"answer":0,"explanation":"UJALA used bulk procurement to cut LED prices and sold them to households, saving power and reducing peak demand. Free connections came under Saubhagya and solar pumps under PM-KUSUM.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-184","question":"Under the UDAY scheme of 2015 to revive power distribution companies, States were to take over what share of their discoms’ debt as on 30 September 2015?","options":["50%","75%","25%","100%"],"answer":1,"explanation":"States were to absorb 75% of discom debt over two years (50% in 2015–16 and 25% in 2016–17), while discoms committed to cut losses and close the gap between cost and revenue.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-185","question":"Which scheme, launched in 2017, aimed at giving electricity connections to all remaining households in rural and urban areas?","options":["Deen Dayal Upadhyaya Gram Jyoti Yojana (DDUGJY)","Ujwal DISCOM Assurance Yojana (UDAY)","Integrated Power Development Scheme (IPDS)","Sahaj Bijli Har Ghar Yojana (Saubhagya)"],"answer":3,"explanation":"Saubhagya targeted last-mile household connections. DDUGJY (2014) focused on village electrification and feeder separation, UDAY on discom finances and IPDS on urban networks.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-186","question":"Match the PM-KUSUM component with its purpose: A. Component A  B. Component B  C. Component C; 1. Solarising existing grid-connected farm pumps  2. Small solar or other renewable power plants on barren or fallow land  3. Standalone off-grid solar pumps","options":["A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2","A-2, B-3, C-1"],"answer":3,"explanation":"Component A sets up decentralised grid-connected plants on farmers’ land, B gives standalone solar pumps where there is no grid, and C solarises existing grid-connected pumps so farmers can sell surplus power.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-187","question":"The Lead Bank Scheme, introduced in 1969, under which one bank coordinates credit planning in each district, grew out of the recommendations of:","options":["The Narasimham Working Group and the Shivaraman Committee","The Gadgil Study Group and the Nariman Committee","The Khusro Committee and the Rangarajan Committee","The Tandon Committee and the Chore Committee"],"answer":1,"explanation":"The Gadgil Study Group proposed an ‘area approach’ to bank lending and the Nariman Committee suggested that each district be allotted to a lead bank. Narasimham’s 1975 group led to the RRBs.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-188","question":"Regional Rural Banks were first set up in 1975 on the recommendation of the:","options":["Narasimham Working Group","Khusro Committee on Agricultural Credit","Rangarajan Committee","Venkatachalam Committee"],"answer":0,"explanation":"The 1975 Working Group on Rural Banks under M. Narasimham recommended RRBs to combine local feel with commercial bank organisation; the first RRBs began in October 1975 and the RRB Act followed in 1976.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-189","question":"NABARD was set up in 1982 on the recommendation of a committee (CRAFICARD) appointed by the RBI and chaired by:","options":["M. Narasimham","A. M. Khusro","B. Sivaraman","C. Rangarajan"],"answer":2,"explanation":"The Committee to Review Arrangements for Institutional Credit for Agriculture and Rural Development, under B. Sivaraman, recommended an apex development bank, and NABARD took over the RBI’s agricultural credit functions.","difficulty":"hard","source":"RBI Grade B"},
  {"id":"eco-sectors-schemes-190","question":"For domestic scheduled commercial banks, the overall priority sector lending target, as a share of adjusted net bank credit (or credit equivalent of off-balance-sheet exposure, whichever is higher), is:","options":["18%","32%","75%","40%"],"answer":3,"explanation":"Domestic commercial banks must lend 40% of ANBC to the priority sector, within which agriculture has an 18% sub-target. Regional Rural Banks have a higher overall target of 75%.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-191","question":"Priority Sector Lending Certificates (PSLCs), introduced by the RBI in 2016, allow a bank that has exceeded its priority sector targets to:","options":["Sell the underlying loans outright to a bank that has fallen short","Convert its surplus priority loans into tax-free infrastructure bonds","Sell its surplus achievement to a short bank while keeping the loans","Carry the surplus forward to meet its targets over the next five years"],"answer":2,"explanation":"A PSLC trades only the priority sector ‘achievement’: the buyer counts it towards its target while the loans and their credit risk stay with the seller. This rewards banks good at such lending.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-sectors-schemes-192","question":"In 2018–19, the Kisan Credit Card facility was extended to:","options":["Farmers engaged in animal husbandry and fisheries","Tenant farmers in the North-Eastern States only","Agricultural labourers without any land","Farmer producer companies with large annual turnover"],"answer":0,"explanation":"The KCC, introduced in 1998 for crop loans, was extended to the working capital needs of farmers in animal husbandry and fisheries, recognising that many farm households depend on livestock and fish.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-193","question":"Under the Modified Interest Subvention Scheme, short-term crop loans of up to ₹3 lakh are given at 7% a year. What effective rate does a farmer who repays promptly pay?","options":["5.5%","3%","4%","7%"],"answer":2,"explanation":"Banks lend at 7% with interest subvention from the Centre, and farmers who repay on time get a further 3% prompt repayment incentive, so their effective rate is 4%.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-194","question":"Under the traditional APMC system, a farmer generally had to sell notified produce:","options":["Directly to the Food Corporation of India at the minimum support price","To any buyer anywhere in the country through an online trading platform","Only to registered cooperatives at prices fixed by the State government","At regulated market yards through licensed traders and commission agents"],"answer":3,"explanation":"State APMC Acts required notified produce to be traded in regulated market yards, with licensed traders and commission agents. This curbed exploitation but also fragmented markets, which e-NAM and model Acts tried to fix.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-195","question":"The central scheme launched in 2020 for forming and promoting Farmer Producer Organisations set a target of how many new FPOs?","options":["1,000","5,000","10,000","50,000"],"answer":2,"explanation":"The scheme for 10,000 new FPOs gives them handholding support for five years, an equity grant and credit guarantee, so that small farmers can gain bargaining power by pooling produce.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-196","question":"Negotiable warehouse receipts issued by warehouses registered with the WDRA help farmers mainly by:","options":["Guaranteeing that the government will buy the stored produce at the MSP","Exempting the stored produce from GST until it is finally sold to a buyer","Letting them pledge stored produce for loans instead of selling at harvest","Allowing them to export the stored produce without any export licence"],"answer":2,"explanation":"Under the Warehousing (Development and Regulation) Act, 2007, a negotiable receipt can be used as collateral or transferred, so farmers get credit against stored grain and can wait for better prices.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-197","question":"The Food Corporation of India was set up in 1965 under:","options":["A resolution of the Union Cabinet","The Food Corporations Act, 1964","The Essential Commodities Act, 1955","The Companies Act, 1956"],"answer":1,"explanation":"FCI is a statutory body created under the Food Corporations Act, 1964, to procure, store and distribute foodgrains and maintain buffer stocks. The Agricultural Prices Commission was set up the same year.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-198","question":"The Pradhan Mantri Matsya Sampada Yojana, launched in 2020, is aimed at the development of:","options":["Fisheries and aquaculture","Dairy and animal husbandry","Horticulture and floriculture","Sericulture and apiculture"],"answer":0,"explanation":"PMMSY is a flagship scheme of the Department of Fisheries to raise fish production, modernise the value chain and improve the welfare of fishers, a key part of the ‘Blue Revolution’.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-199","question":"The Rashtriya Gokul Mission, launched in 2014, focuses on:","options":["Raising milk output through imported exotic cattle breeds","Conserving and improving indigenous bovine breeds","Building milk-chilling plants for village dairy cooperatives","Insuring cattle owners against loss from disease"],"answer":1,"explanation":"The mission promotes the development and conservation of indigenous cattle and buffalo breeds through breeding programmes, artificial insemination and Gokul Grams.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-200","question":"Operation Barga, launched in West Bengal in 1978, was mainly about:","options":["Distributing surplus land acquired under the land ceiling laws","Recording sharecroppers to secure their tenancy rights","Consolidating scattered holdings into compact plots for each farmer","Settling landless families on forest land as cultivators"],"answer":1,"explanation":"Operation Barga registered bargadars (sharecroppers) in the land records, giving them security of tenancy and a legal share of the crop; it was a tenancy reform rather than land redistribution.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-201","question":"The Bhoodan movement, in which landowners were asked to donate land for the landless, was started in 1951 by:","options":["Jayaprakash Narayan","Vinoba Bhave","Ram Manohar Lohia","Acharya Kripalani"],"answer":1,"explanation":"Vinoba Bhave began Bhoodan at Pochampally in present-day Telangana in 1951, and it later grew into Gramdan; Jayaprakash Narayan joined and supported the movement.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-202","question":"‘Baumol’s cost disease’ explains why:","options":["Manufacturing costs rise faster than service costs as the economy grows richer over time","Farm costs fall as mechanisation spreads, pushing surplus labour from villages into cities","Public sector costs fall steadily when services are outsourced to private firms","Costs of services like teaching keep rising, as their productivity lags but wages keep pace"],"answer":3,"explanation":"In services like education, health care and live arts, output per worker grows little, but wages must keep up with high-productivity sectors, so their relative cost and share of spending rise.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-sectors-schemes-203","question":"‘Premature deindustrialisation’, a term linked with Dani Rodrik, describes economies in which:","options":["Manufacturing’s share peaks at much lower incomes than it did for early industrialisers","Manufacturing grows faster than services before the economy reaches middle income","Governments close loss-making state factories before they privatise the rest of them","Agriculture’s share of employment falls before its share of national output does"],"answer":0,"explanation":"Many developing countries, India among the cases discussed, are moving into services while manufacturing’s share is still small and incomes are low, unlike the path of the early industrialisers.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-204","question":"‘Dutch disease’ refers to a situation in which:","options":["A resource export boom lifts the real exchange rate and hurts manufacturing exports","A country’s farm sector shrinks because of repeated floods and rising sea levels","High import tariffs protect domestic manufacturing but raise prices for consumers","An outflow of skilled workers lowers productivity in the country’s service sector"],"answer":0,"explanation":"The term comes from the Netherlands after its gas discoveries: resource exports and inflows push up the currency and wages, making manufacturing and other exports less competitive.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-sectors-schemes-205","question":"Albert Hirschman’s strategy of ‘unbalanced growth’ favoured putting scarce investment into industries that:","options":["Need the least amount of capital per worker employed","Have the strongest backward and forward linkages","Earn the most foreign exchange in the short run","Serve the largest number of final consumers"],"answer":1,"explanation":"Hirschman argued that investing in key sectors with strong linkages creates shortages and pressures that induce investment elsewhere. Nurkse, by contrast, argued for balanced growth across many sectors at once.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-206","question":"Rosenstein-Rodan’s ‘big push’ theory argues that a poor economy needs:","options":["A large, coordinated investment across many complementary industries at once","Gradual growth led by small farms, village crafts and cottage industries","Rapid opening to imports so that foreign competition forces domestic efficiency","Large foreign loans so that it can first repay all its old external debt"],"answer":0,"explanation":"Because industries depend on each other for demand and inputs, isolated investments may fail; a simultaneous push across sectors lets each create markets for the others, overcoming indivisibilities.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-207","question":"In the Harris–Todaro model, migrants compare the rural wage with the expected urban wage. If the rural wage is ₹300 a day and the urban formal-sector wage ₹750, migration stops when the urban unemployment rate reaches:","options":["40%","45%","25%","60%"],"answer":3,"explanation":"Migration stops when (probability of getting an urban job) × 750 = 300, i.e. a 40% chance of employment, which means 60% urban unemployment. Answering 40% confuses the employment probability with the unemployment rate.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-sectors-schemes-208","question":"Engel’s law helps explain the falling share of agriculture in national output because:","options":["Farm prices always rise faster than industrial prices","As incomes rise, the share of spending on food falls","Land is fixed, so farm output cannot grow at all","Governments tax agriculture more heavily than industry"],"answer":1,"explanation":"Food demand grows more slowly than income, so as incomes rise, a smaller share of spending goes to farm products and demand shifts to industry and services.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-209","question":"The National Commission for Enterprises in the Unorganised Sector (2007), under Arjun Sengupta, defined the unorganised sector as unincorporated private enterprises owned by individuals or households, employing fewer than:","options":["5 workers","10 workers","20 workers","50 workers"],"answer":1,"explanation":"NCEUS counted enterprises run on a proprietary or partnership basis with fewer than ten workers as unorganised; unorganised workers also include informal workers in the organised sector who lack social security.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-210","question":"The Industrial Relations Code, 2020 raised the threshold above which an industrial establishment needs prior government permission for lay-off, retrenchment or closure from 100 workers to:","options":["200 workers","250 workers","500 workers","300 workers"],"answer":3,"explanation":"The Code raised the limit to 300 workers, and lets the government raise it further by notification, to give firms more flexibility; earlier the Industrial Disputes Act set it at 100.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-211","question":"The Code on Wages, 2019 empowers the Central Government to fix a ‘floor wage’. Its effect is that:","options":["Every employer must pay at least the floor wage plus a dearness allowance","No State may fix a minimum wage below the floor wage","The floor wage replaces all State minimum wages","Only Central Government employees are paid the floor wage"],"answer":1,"explanation":"The Centre fixes the floor wage, possibly different for different areas, considering minimum living standards; State minimum wages cannot be lower than it.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-212","question":"The National Payments Corporation of India, which runs UPI and RuPay, is:","options":["A department of the Reserve Bank of India set up under the RBI Act, 1934","A public sector undertaking owned wholly by the Ministry of Finance","A statutory body created under the Payment and Settlement Systems Act, 2007","A not-for-profit company promoted by the RBI and Indian Banks’ Association"],"answer":3,"explanation":"NPCI was set up in 2008 as a not-for-profit (Section 8) company under the RBI’s guidance and the IBA, owned by banks, as an umbrella organisation for retail payments.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-213","question":"The Open Network for Digital Commerce (ONDC), backed by DPIIT, aims to:","options":["Set up a government-owned e-commerce company to compete with private platforms","Tax foreign e-commerce companies on all sales they make to buyers in India","Let buyers and sellers on different apps transact through common open protocols","Ban private-label goods sold by the large online marketplaces in India"],"answer":2,"explanation":"ONDC is a network, not a platform: open protocols let any buyer app reach any seller app, so small sellers are not locked into one marketplace.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-sectors-schemes-214","question":"BharatNet, earlier called the National Optical Fibre Network, aims to:","options":["Provide satellite phones to remote villages along the borders","Lay undersea optical cables to the island territories only","Connect all gram panchayats with broadband optical fibre","Give free smartphones to every poor rural household in India"],"answer":2,"explanation":"Started as NOFN in 2011 and renamed BharatNet in 2015, it builds optical fibre middle-mile connectivity to every gram panchayat so that broadband can reach villages.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-215","question":"The National Investment and Infrastructure Fund (NIIF), set up in 2015, is best described as:","options":["A department of the Finance Ministry that directly funds highways","A non-banking finance company owned wholly by the Reserve Bank","A pension fund regulated by PFRDA for infrastructure workers","A quasi-sovereign wealth fund in which the Government holds 49%"],"answer":3,"explanation":"NIIF is India’s first quasi-sovereign wealth fund; the Government holds 49% so that it is not a government company, and the rest comes from domestic and foreign institutional investors.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-216","question":"How many of these statements about InvITs and REITs in India are correct? I. Both are regulated by SEBI under regulations issued in 2014. II. An InvIT holds income-generating infrastructure assets such as roads or power lines. III. A REIT holds completed, rent-generating real estate such as office parks. IV. Both are required to distribute a large part of their cash flows to unit holders.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Both are trust-based vehicles that pool investors’ money in yield-generating assets and pass on most of the cash flow, letting developers recycle capital.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-sectors-schemes-217","question":"The National Monetisation Pipeline, announced in 2021, plans to raise money mainly by:","options":["Leasing brownfield assets to private firms for a period, keeping ownership","Selling government land outright to private developers through auctions","Issuing special bonds to the RBI against the value of infrastructure assets","Privatising all public sector banks and insurance companies in stages"],"answer":0,"explanation":"Under the NMP, assets such as roads, railway stations and pipelines are handed to private players through models like TOT and InvITs for a set period, after which they return to the government.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-218","question":"In the ‘Swiss challenge’ method of awarding public projects:","options":["The lowest bidder wins automatically after a single sealed round of bidding","The project goes to a foreign firm with a proven track record in such work","Rival bids are invited on an unsolicited proposal, whose author may match the best","The government negotiates privately with one firm without any open bidding"],"answer":2,"explanation":"A private party proposes a project; the government invites counter-proposals, and the original proponent gets the right to match the best offer to win the contract.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-219","question":"The National Bank for Financing Infrastructure and Development (NaBFID) was set up in 2021 as:","options":["A development finance institution created by an Act of Parliament","A wholly owned subsidiary of the State Bank of India for infra loans","A division of NITI Aayog for infrastructure planning","A non-banking finance company jointly owned by the States"],"answer":0,"explanation":"NaBFID was created under the NaBFID Act, 2021 as a development finance institution for long-term infrastructure funding, reviving the DFI model that had faded after ICICI and IDBI turned into banks.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-220","question":"PM-JANMAN, launched in November 2023, is a mission specifically for:","options":["All Scheduled Caste households living in rural areas","Particularly Vulnerable Tribal Groups","Nomadic and denotified tribes living in cities","Forest dwellers who hold rights under the Forest Rights Act"],"answer":1,"explanation":"The Pradhan Mantri Janjati Adivasi Nyaya Maha Abhiyan targets the 75 PVTGs, bringing housing, roads, water, health and other services to their habitations through several ministries.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-221","question":"The Pradhan Mantri Van Dhan Yojana, launched in 2018 through TRIFED, mainly aims to:","options":["Plant trees on degraded forest land with MGNREGA labour and funds","Pay tribal families a yearly fee for protecting forests from fire","Add value to minor forest produce through tribal producer groups","Give tribal youth bank loans to set up timber trading businesses"],"answer":2,"explanation":"Van Dhan Vikas Kendras organise tribal gatherers into groups that process, package and market minor forest produce, raising the share of the final price that reaches them.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-222","question":"A ‘Lakhpati Didi’ under the initiative announced in 2023 is a member of a self-help group who:","options":["Has taken a bank loan of at least ₹1 lakh for her business","Has saved at least ₹1 lakh in her SHG savings account","Has received a one-time grant of ₹1 lakh from the State","Earns a household income of at least ₹1 lakh a year"],"answer":3,"explanation":"The initiative under DAY-NRLM aims to help SHG women reach a sustained annual household income of ₹1 lakh or more through livelihood activities, skills and credit.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-223","question":"Under Phase II of the Swachh Bharat Mission (Grameen), the goal of ‘ODF Plus’ means:","options":["Building a second, separate toilet in every rural household","Declaring all towns as well as all villages open-defecation free","Replacing all rural pit latrines with piped sewer connections","Keeping villages ODF and adding solid and liquid waste management"],"answer":3,"explanation":"Phase II (from 2020–21) moved beyond toilet building to keeping villages ODF and managing solid and liquid waste so that villages are visibly clean.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-224","question":"The Credit Linked Subsidy Scheme (CLSS) under PMAY-Urban provided:","options":["Free houses built by the government for the urban homeless","Interest subsidy on home loans for EWS, LIG and MIG families","Rent support to migrant workers in rental housing complexes","Grants to builders who construct affordable housing projects"],"answer":1,"explanation":"Under CLSS, the subsidy on the interest of a home loan was credited upfront to the borrower’s loan account, lowering EMIs for economically weaker sections and low- and middle-income groups.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-sectors-schemes-225","question":"The Atal Bhujal Yojana, launched in 2019 with World Bank support, focuses on:","options":["Piped drinking water connections to every rural home","Interlinking rivers to move surplus water to drought-prone regions","Community-led management of groundwater in water-stressed areas","Building large storage dams in drought-prone districts"],"answer":2,"explanation":"Atal Jal works in water-stressed areas of seven States, using incentives for gram panchayats that plan water budgets and reduce groundwater use. Tap connections are the Jal Jeevan Mission’s job.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-226","question":"The National Food Security Mission, launched in 2007–08, was originally meant to raise the production of:","options":["Rice, wheat and pulses","Oilseeds, sugarcane and cotton","Fruits, vegetables and spices","Milk, eggs and fish"],"answer":0,"explanation":"NFSM began with rice, wheat and pulses through area expansion and productivity gains in identified districts; coarse cereals and nutri-cereals were added later.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-227","question":"The Rashtriya Krishi Vikas Yojana (2007) differs from many other farm schemes because it:","options":["Pays a fixed sum directly into every farmer’s bank account","Lets States plan and choose their own farm projects","Is funded entirely through loans taken from the World Bank","Is run only in districts with no assured irrigation"],"answer":1,"explanation":"RKVY was designed to encourage States to raise farm investment, letting them prepare district and State agriculture plans and pick projects suited to local needs.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-228","question":"Under the National Food Security Act, 2013, if a beneficiary is not supplied the entitled foodgrains or meals, he or she is entitled to:","options":["Double the quantity of foodgrains in the next month","A food security allowance from the State government","A cash refund paid by the Food Corporation of India","Free foodgrains from the Centre for the next six months"],"answer":1,"explanation":"Section 8 of the Act requires the State government to pay a food security allowance in such cases. It is one of the provisions that make the Act a legal entitlement rather than a welfare scheme.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-229","question":"The National Manufacturing Policy of 2011 aimed to raise the share of manufacturing in GDP, over a decade, to:","options":["25%","15%","35%","50%"],"answer":0,"explanation":"The policy targeted a 25% share and 100 million additional jobs, and proposed National Investment and Manufacturing Zones; the share stayed far below this, closer to the mid-teens.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-230","question":"The Jan Vishwas (Amendment of Provisions) Act, 2023 sought to improve ease of doing business mainly by:","options":["Turning many minor offences in central laws into civil penalties","Abolishing all licences needed for setting up new factories","Merging the central labour laws into four new labour codes","Allowing 100% FDI in all sectors through the automatic route"],"answer":0,"explanation":"The Act amended about 180 provisions across 42 central Acts, turning many minor, technical or procedural lapses into civil matters with monetary penalties to reduce fear of prosecution.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-231","question":"In 2020 the coal sector in India was opened to commercial mining, which means that:","options":["Private firms may mine coal for sale, not just for their own plants","Coal India Limited was privatised through a majority stake sale","Coal imports were banned to protect the domestic mining industry","States lost their right to receive royalty on coal mined there"],"answer":0,"explanation":"Earlier, private firms could mine coal only for captive use in their own power, steel or cement plants. Commercial auctions allow sale without end-use restrictions, while Coal India stays public.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-232","question":"District Mineral Foundations, provided for by the MMDR Amendment Act, 2015, are funded mainly by:","options":["Grants from the Union budget for the most backward districts","A share of the GST collected on minerals and mining services","Loans from NABARD to districts with large mining activity","Mining leaseholders’ contributions linked to their royalty"],"answer":3,"explanation":"Leaseholders pay a contribution related to their royalty into the DMF of the district, which spends it on people and areas affected by mining, guided by the PMKKKY scheme.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-233","question":"The Swadesh Darshan scheme of the Ministry of Tourism is meant to:","options":["Give tax refunds to foreign tourists on goods bought in India","Develop theme-based tourist circuits across the country","Fund pilgrimage trips for senior citizens","Promote Indian films abroad to attract visitors"],"answer":1,"explanation":"Launched in 2014–15, it funds integrated infrastructure on theme-based circuits such as Buddhist, coastal or heritage circuits; PRASHAD covers pilgrimage sites separately.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-234","question":"The India Semiconductor Mission, launched in 2021, works as a specialised division under:","options":["The Department of Science and Technology","The Indian Space Research Organisation","Digital India Corporation under MeitY","The Ministry of Heavy Industries"],"answer":2,"explanation":"ISM operates within Digital India Corporation under MeitY, running the incentive programmes for semiconductor fabs, display fabs, and assembly and testing units.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-235","question":"The Software Technology Parks of India (STPI) scheme, started in 1991, helped the IT industry mainly by:","options":["Reserving all government software work for public sector firms","Fixing the salaries of software engineers across the country","Banning imports of foreign software to protect Indian firms","Giving export software units tax breaks and fast data links"],"answer":3,"explanation":"STPI gave 100% export-oriented software units single-window clearance, duty-free imports, tax holidays and high-speed satellite data links, which helped IT exports take off in the 1990s.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-236","question":"The ‘U-shaped’ pattern of female labour force participation, discussed by Claudia Goldin, suggests that as an economy develops:","options":["Women’s participation rises steadily with income","Women’s participation falls steadily with income","Women’s participation first falls and then rises","Women’s participation stays flat at all income levels"],"answer":2,"explanation":"As farm-based family work declines and household incomes rise, participation first falls; it rises again as women’s education grows and suitable service-sector jobs expand. It is one lens on India’s low female LFPR.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-237","question":"A worker who works only 20 hours a week and is willing and available to work more is an example of:","options":["Visible underemployment","Disguised unemployment","Frictional unemployment","Open unemployment"],"answer":0,"explanation":"Visible underemployment means working fewer hours than normal while wanting more work. Disguised unemployment is when extra workers add nothing to output, though they appear fully engaged.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-238","question":"On a Lorenz curve diagram, the area between the line of equality and the Lorenz curve is 0.15 (the whole square has area 1). The Gini coefficient is:","options":["0.15","0.30","0.35","0.70"],"answer":1,"explanation":"Gini = area between the line of equality and the Lorenz curve ÷ total area under the line of equality (0.5) = 0.15/0.5 = 0.30. Taking 0.15 directly forgets that the triangle is half the square.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-239","question":"The 1979 Task Force under Y. K. Alagh defined the poverty line using calorie norms of:","options":["2,100 kcal a day in rural areas and 2,400 in urban areas","2,400 kcal a day in rural areas and 2,100 in urban areas","2,250 kcal a day in both rural and urban areas","1,800 kcal a day in rural areas and 2,100 in urban areas"],"answer":1,"explanation":"Rural people were assumed to need more energy for manual work, hence 2,400 kcal rural and 2,100 kcal urban; the poverty line was the spending at which these were met.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-240","question":"A key change made by the Tendulkar Committee (2009) in measuring poverty was that it:","options":["Raised the calorie norm for rural areas to 2,700 kcal a day per person","Dropped the calorie anchor and used one basket for rural and urban areas","Measured poverty by household income rather than by consumption spending","Counted only food spending and left out health and education costs"],"answer":1,"explanation":"Tendulkar moved away from calorie norms, used the urban poverty line basket for both rural and urban areas with price adjustments, and allowed for private spending on health and education.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-241","question":"In a region, 20% of people are multidimensionally poor (H) and on average they are deprived in 45% of the weighted indicators (A). The Multidimensional Poverty Index is:","options":["0.20","0.45","0.09","0.65"],"answer":2,"explanation":"MPI = H × A = 0.20 × 0.45 = 0.09. It falls if fewer people are poor or if the poor become less deprived, which the head-count ratio alone would miss.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-sectors-schemes-242","question":"The Inequality-adjusted Human Development Index (IHDI) differs from the HDI in that it:","options":["Adds a fourth dimension measuring gaps between women and men","Uses only income per head and ignores health and education","Compares a country’s HDI with the average of its neighbours","Discounts each dimension for how unequally it is spread"],"answer":3,"explanation":"The IHDI lowers each dimension’s value according to inequality within the population; the gap between HDI and IHDI shows the loss in human development due to inequality.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-243","question":"In a country, 25% of the population is aged 0–14, 68% is aged 15–64 and 7% is 65 or older. Its total dependency ratio is about:","options":["32%","37%","68%","47%"],"answer":3,"explanation":"Dependency ratio = (0–14 + 65+)/(15–64) = 32/68 ≈ 47%. Using 32% forgets to divide by the working-age group; 37% counts only the young.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-244","question":"Under the RBI’s regulatory framework for microfinance of 2022, a microfinance loan is a collateral-free loan to a household with an annual income of up to:","options":["₹1.25 lakh","₹2 lakh","₹5 lakh","₹3 lakh"],"answer":3,"explanation":"The 2022 framework set a common income ceiling of ₹3 lakh for rural and urban households, applied it to all regulated lenders, and capped loan repayments at 50% of household income.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-sectors-schemes-245","question":"Mission Amrit Sarovar, launched in 2022, aims to:","options":["Build or revive 75 water bodies in every district","Clean 75 polluted stretches of the river Ganga and tributaries","Provide piped water to 75 towns in each State","Set up 75 sewage treatment plants in big cities"],"answer":0,"explanation":"The mission, marking 75 years of independence, set a target of 75 Amrit Sarovars (ponds) per district, largely using MGNREGA and other schemes, to conserve rainwater.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-246","question":"Which MSME Ministry scheme, relaunched in 2022, certifies units at Bronze, Silver and Gold levels on both product quality and environmental impact?","options":["Lean Manufacturing Competitiveness Scheme","BIS product certification (ISI mark)","ZED Certification Scheme","Udyam Registration"],"answer":2,"explanation":"ZED (Zero Defect Zero Effect) certifies MSMEs in Bronze, Silver and Gold tiers for quality and low environmental impact. The Lean scheme is tempting because it targets waste and productivity, but it is a consultancy-support scheme, not a graded quality-and-environment certification.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eco-sectors-schemes-247","question":"Guarantees under the Emergency Credit Line Guarantee Scheme, launched in 2020 to help businesses through the pandemic, were provided by:","options":["The Reserve Bank of India","SIDBI","National Credit Guarantee Trustee Company","Export Credit Guarantee Corporation of India"],"answer":2,"explanation":"ECLGS loans by banks and NBFCs carried a full guarantee from NCGTC, a company of the Department of Financial Services, so lenders could extend extra credit to MSMEs and others hit by COVID-19.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-sectors-schemes-248","question":"Assertion (A): Many workers employed by organised-sector firms are counted as informal workers. Reason (R): Informality of employment depends on whether a worker has social security and a written contract, not just on the type of enterprise.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Contract and casual workers in registered firms often lack social security and job security, so they are informal workers in the organised sector; the distinction is between enterprise type and job type.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-sectors-schemes-249","question":"The Industries (Development and Regulation) Act, the main law behind industrial licensing, was enacted in:","options":["1948","1956","1951","1969"],"answer":2,"explanation":"The IDR Act of 1951 gave the Centre power to license and regulate industries; 1948 and 1956 were the Industrial Policy Resolutions, and 1969 saw the MRTP Act and bank nationalisation.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-250","question":"The PM Formalisation of Micro Food Processing Enterprises (PMFME) scheme, launched in 2020, follows which approach in choosing products for support?","options":["One District One Product","One Nation One Ration Card","One State One Crop","One Block One Cluster"],"answer":0,"explanation":"PMFME, under the Ministry of Food Processing Industries, supports micro food units with credit-linked subsidy, and uses ODOP to gain scale in buying inputs, common services and marketing.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-sectors-schemes-251","question":"Which voluntary, contributory scheme launched in 2019 offers small and marginal farmers who join between the ages of 18 and 40 a pension of ₹3,000 a month from the age of 60?","options":["Atal Pension Yojana","PM Shram Yogi Maan-dhan","PM-KISAN income support","PM Kisan Maan-Dhan Yojana"],"answer":3,"explanation":"PM-KMY is the farmers’ counterpart of PM-SYM (which covers unorganised workers): the Centre matches the farmer’s contribution and LIC manages the fund. PM-KISAN is income support, not a pension.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
];

export default questions;
